-- LAT Pakistan Studies: 106 original MCQs, PST-0001 to PST-0106 (HEC LAT Part I has 10 Pakistan Studies MCQs).
-- Chapters follow the topics LAT prep guides group the subject into (lib/banks.ts latSyllabus): Muslim rule in South
-- Asia, the Pakistan Movement, Pakistan since 1947, the constitutions, geography, economy and culture, and foreign
-- relations. Written for Markhor Prep in the style of past LAT papers (short factual stems, four options), not copied
-- from any book. Each key was checked against the source named in the question (the Constitution, official bodies,
-- UNESCO, standard Pakistan Studies texts); facts that change often (office-holders, seat counts) are left out.
--
-- These subjects are also planned for the government jobs tests, so questions.mdcat = 0 keeps them out of the
-- pre-medical banks and each is listed in the LAT bank under its own chapter. Not in the free set.

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Pakistan Studies', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('PST-0001', 'Ancient and Muslim rule in South Asia', 'Indus Valley Civilisation', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: UNESCO World Heritage List, Archaeological Ruins at Moenjodaro', 'The ruins of Mohenjo-daro, a city of the Indus Valley Civilisation, are in which province?', '["Khyber Pakhtunkhwa", "Balochistan", "Punjab", "Sindh"]', 3, 'Mohenjo-daro lies in Larkana district of Sindh, beside the Indus. It is a UNESCO World Heritage Site.', '{"0": "Takht-i-Bahi and other Gandhara sites are here, not Mohenjo-daro.", "1": "Mehrgarh, an older farming site, is in Balochistan, not Mohenjo-daro.", "2": "Harappa, the other famous Indus city, is in Punjab."}'),
  ('PST-0002', 'Ancient and Muslim rule in South Asia', 'Indus Valley Civilisation', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Department of Archaeology and Museums, Government of Pakistan: Harappa', 'Harappa, which gave the Indus Valley Civilisation its other name, is in which district of Punjab?', '["Bahawalpur", "Sahiwal", "Jhelum", "Attock"]', 1, 'Harappa lies near the old course of the Ravi in Sahiwal district, Punjab.', '{"0": "Bahawalpur is the Cholistan region; Harappa is near the Ravi in Sahiwal.", "2": "Jhelum is known for Rohtas Fort and the Salt Range, not Harappa.", "3": "Attock is on the Indus near its meeting with the Kabul River; Harappa is far to the south-east."}'),
  ('PST-0003', 'Ancient and Muslim rule in South Asia', 'Gandhara', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: UNESCO World Heritage List, Taxila', 'Taxila was a great centre of which ancient civilisation?', '["Gandhara", "Mesopotamia", "Indus Valley", "Persian Achaemenid capital"]', 0, 'Taxila (Rawalpindi district) was a leading city and Buddhist learning centre of Gandhara.', '{"1": "Mesopotamia was between the Tigris and Euphrates, in present-day Iraq.", "2": "The Indus cities (Harappa, Mohenjo-daro) are much older; Taxila flourished later, under Gandhara.", "3": "Taxila was ruled by the Achaemenids for a time, but their capitals were Persepolis and Susa in Iran."}'),
  ('PST-0004', 'Ancient and Muslim rule in South Asia', 'Arab conquest of Sindh', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Muslim conquest of Sindh', 'Muhammad bin Qasim conquered Sindh in the year:', '["712 AD", "1001 AD", "1526 AD", "1192 AD"]', 0, 'Muhammad bin Qasim took Debal and defeated Raja Dahir in 711-712 AD; 712 AD is the usual date for the conquest of Sindh.', '{"1": "1001 AD is the start of Mahmud of Ghazni''s raids.", "2": "1526 AD is the First Battle of Panipat, which began Mughal rule.", "3": "1192 AD is the Second Battle of Tarain, won by Muhammad Ghori."}'),
  ('PST-0005', 'Ancient and Muslim rule in South Asia', 'Arab conquest of Sindh', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Muslim conquest of Sindh', 'Muhammad bin Qasim defeated which ruler of Sindh?', '["Raja Dahir", "Raja Jaipal", "Ibrahim Lodi", "Prithviraj Chauhan"]', 0, 'Raja Dahir, the ruler of Sindh, was killed in battle against Muhammad bin Qasim in 712 AD.', '{"1": "Raja Jaipal of the Hindu Shahi dynasty fought Mahmud of Ghazni.", "2": "Ibrahim Lodi was defeated by Babur at Panipat in 1526.", "3": "Prithviraj Chauhan was defeated by Muhammad Ghori at Tarain in 1192."}'),
  ('PST-0006', 'Ancient and Muslim rule in South Asia', 'Ghaznavids and Ghorids', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Ghorid conquest', 'In the Second Battle of Tarain (1192), Muhammad Ghori defeated:', '["Hemu", "Prithviraj Chauhan", "Raja Dahir", "Rana Sanga"]', 1, 'Muhammad Ghori lost the first battle at Tarain in 1191 but defeated Prithviraj Chauhan there in 1192, opening north India to Muslim rule.', '{"0": "Hemu was defeated at the Second Battle of Panipat in 1556.", "2": "Raja Dahir was defeated by Muhammad bin Qasim in 712.", "3": "Rana Sanga fought Babur at Khanwa in 1527."}'),
  ('PST-0007', 'Ancient and Muslim rule in South Asia', 'Delhi Sultanate', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Delhi Sultanate', 'Who founded the Delhi Sultanate in 1206?', '["Alauddin Khilji", "Qutb-ud-din Aibak", "Balban", "Iltutmish"]', 1, 'Qutb-ud-din Aibak, a former slave-general of Muhammad Ghori, became the first Sultan of Delhi in 1206, founding the Slave (Mamluk) dynasty.', '{"0": "Alauddin Khilji ruled from 1296, under the Khilji dynasty.", "2": "Balban ruled later (1266-1287) in the same Slave dynasty.", "3": "Iltutmish was Aibak''s successor and son-in-law."}'),
  ('PST-0008', 'Ancient and Muslim rule in South Asia', 'Mughal Empire', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Mughal Empire', 'The Mughal Empire began after Babur defeated Ibrahim Lodi at the First Battle of:', '["Plassey (1757)", "Tarain (1192)", "Khanwa (1527)", "Panipat (1526)"]', 3, 'Babur''s victory at Panipat in 1526 ended the Lodi dynasty and founded the Mughal Empire.', '{"0": "Plassey was won by Robert Clive against Siraj-ud-Daulah.", "1": "Tarain was won by Muhammad Ghori against Prithviraj Chauhan.", "2": "Babur won Khanwa a year after Panipat, against Rana Sanga; it did not begin his rule."}'),
  ('PST-0009', 'Ancient and Muslim rule in South Asia', 'Mughal Empire', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Muslim revival in the Mughal era', 'Which saint openly opposed Emperor Akbar''s Din-i-Ilahi?', '["Sheikh Ahmad Sirhindi (Mujaddid Alf Sani)", "Shah Waliullah", "Khwaja Moinuddin Chishti", "Data Ganj Bakhsh"]', 0, 'Sheikh Ahmad Sirhindi, known as Mujaddid Alf Sani, worked against Din-i-Ilahi during the reigns of Akbar and Jahangir.', '{"1": "Shah Waliullah lived in the 18th century, long after Akbar.", "2": "Khwaja Moinuddin Chishti of Ajmer died in the 13th century.", "3": "Data Ganj Bakhsh (Ali Hujwiri) lived in the 11th century in Lahore."}'),
  ('PST-0010', 'Ancient and Muslim rule in South Asia', 'Mughal architecture', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Mughal architecture', 'The Badshahi Mosque in Lahore was built by:', '["Akbar", "Aurangzeb Alamgir", "Shah Jahan", "Jahangir"]', 1, 'Aurangzeb completed the Badshahi Mosque in 1673-74, opposite the Lahore Fort.', '{"0": "Akbar rebuilt the Lahore Fort but did not build the Badshahi Mosque.", "2": "Shah Jahan built the Shalimar Gardens in Lahore and the Taj Mahal in Agra.", "3": "Jahangir is buried at Shahdara, Lahore; he did not build this mosque."}'),
  ('PST-0011', 'Ancient and Muslim rule in South Asia', 'Mughal architecture', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: UNESCO World Heritage List, Fort and Shalamar Gardens in Lahore', 'The Shalimar Gardens in Lahore were laid out by:', '["Humayun", "Babur", "Shah Jahan", "Aurangzeb"]', 2, 'Shah Jahan laid out the Shalimar Gardens in 1641-42. With the Lahore Fort they are a UNESCO World Heritage Site.', '{"0": "Humayun spent much of his reign in exile and built no garden in Lahore.", "1": "Babur''s gardens were in Kabul and Agra.", "3": "Aurangzeb built the Badshahi Mosque."}'),
  ('PST-0012', 'Ancient and Muslim rule in South Asia', 'Sur dynasty', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: UNESCO World Heritage List, Rohtas Fort', 'Rohtas Fort near Jhelum was built by:', '["Ranjit Singh", "Mahmud of Ghazni", "Sher Shah Suri", "Akbar"]', 2, 'Sher Shah Suri built Rohtas Fort in the 1540s to hold back the Gakhars and the exiled Humayun. It is a UNESCO World Heritage Site.', '{"0": "Ranjit Singh ruled Punjab in the 19th century; Rohtas is from the 1540s.", "1": "Mahmud of Ghazni raided India but built no forts here.", "3": "Akbar built forts at Agra, Lahore and Attock."}'),
  ('PST-0013', 'Ancient and Muslim rule in South Asia', 'Muslim revival', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Shah Waliullah''s reform movement', 'Fath-ur-Rahman, a Persian translation of the Holy Quran made so that ordinary Muslims could understand it, is the work of:', '["Sir Syed Ahmad Khan", "Shah Waliullah", "Mujaddid Alf Sani", "Shah Abdul Aziz"]', 1, 'Shah Waliullah (1703-1762) translated the Quran into Persian (Fath-ur-Rahman), the literary language of the time.', '{"0": "Sir Syed lived a century later and wrote an Urdu commentary (tafsir).", "2": "Mujaddid Alf Sani is known for his letters (Maktubat), not a Quran translation.", "3": "Shah Abdul Aziz was Shah Waliullah''s son; his brothers made Urdu translations."}'),
  ('PST-0014', 'Ancient and Muslim rule in South Asia', 'Muslim revival', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Jihad movement', 'Syed Ahmad Shaheed Barelvi was martyred at the Battle of Balakot in:', '["1857", "1799", "1803", "1831"]', 3, 'Syed Ahmad Barelvi and Shah Ismail were killed fighting the Sikhs at Balakot in May 1831.', '{"0": "1857 is the War of Independence.", "1": "In 1799 Tipu Sultan died at Seringapatam.", "2": "In 1803 the British took Delhi; Balakot came later."}'),
  ('PST-0015', 'Ancient and Muslim rule in South Asia', 'Muslim revival', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Faraizi movement', 'The Faraizi Movement for religious reform among Muslim peasants was started in Bengal by:', '["Haji Shariatullah", "Titu Mir", "Nawab Abdul Latif", "Syed Ahmad Barelvi"]', 0, 'Haji Shariatullah began the Faraizi Movement in the early 19th century, urging Muslims to keep the obligatory duties (faraiz) of Islam.', '{"1": "Titu Mir led a separate peasant uprising in Bengal and died in 1831.", "2": "Nawab Abdul Latif founded the Mohammedan Literary Society in 1863.", "3": "Syed Ahmad Barelvi led the Jihad movement in the north-west."}'),
  ('PST-0016', 'Ancient and Muslim rule in South Asia', 'British East India Company', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Rise of British power', 'The Battle of Plassey (1757), which gave the East India Company control of Bengal, was fought against:', '["Tipu Sultan", "Hyder Ali", "Siraj-ud-Daulah", "Bahadur Shah Zafar"]', 2, 'Robert Clive defeated Siraj-ud-Daulah, Nawab of Bengal, at Plassey in 1757 after Mir Jafar betrayed him.', '{"0": "Tipu Sultan fought the British in Mysore and died in 1799.", "1": "Hyder Ali, Tipu''s father, ruled Mysore.", "3": "Bahadur Shah Zafar was the last Mughal emperor, exiled after 1857."}'),
  ('PST-0017', 'Ancient and Muslim rule in South Asia', 'British East India Company', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Resistance to British rule', 'Tipu Sultan, who died fighting the British in 1799, was the ruler of:', '["Bengal", "Mysore", "Hyderabad Deccan", "Awadh"]', 1, 'Tipu Sultan, the ''Tiger of Mysore'', was killed defending his capital Seringapatam in 1799.', '{"0": "Bengal''s Nawab Siraj-ud-Daulah fell at Plassey in 1757.", "2": "The Nizam of Hyderabad allied with the British against Tipu.", "3": "Awadh was annexed by the British in 1856."}'),
  ('PST-0018', 'Ancient and Muslim rule in South Asia', 'End of Mughal rule', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), War of Independence 1857', 'After the War of Independence of 1857, the last Mughal emperor Bahadur Shah Zafar was exiled to:', '["Kabul", "Andaman Islands", "London", "Rangoon"]', 3, 'Bahadur Shah Zafar was tried by the British and exiled to Rangoon (Yangon), Burma, where he died in 1862.', '{"0": "Kabul was never a place of exile for Bahadur Shah Zafar.", "1": "Many freedom fighters were sent to the Andamans, but Zafar was sent to Rangoon.", "2": "He was not taken to Britain."}'),
  ('PST-0019', 'Ancient and Muslim rule in South Asia', 'Mughal Empire', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Aurangzeb''s reign', 'The collection of Hanafi rulings known as Fatawa-e-Alamgiri was compiled under:', '["Akbar", "Aurangzeb", "Babur", "Shah Jahan"]', 1, 'Aurangzeb Alamgir had scholars compile Fatawa-e-Alamgiri, a code of Islamic law used across his empire.', '{"0": "Akbar''s court produced the Ain-i-Akbari, a record of his administration.", "2": "Babur wrote his memoir, the Tuzk-e-Baburi.", "3": "Shah Jahan is remembered for his buildings, not this legal work."}'),
  ('PST-0020', 'After 1857 and the Pakistan Movement', 'Sir Syed Ahmad Khan', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Aligarh Movement', 'Sir Syed Ahmad Khan founded the Muhammadan Anglo-Oriental school, later Aligarh Muslim University, at:', '["Aligarh", "Lucknow", "Deoband", "Lahore"]', 0, 'Sir Syed opened the MAO school at Aligarh in 1875; it became a college in 1877 and Aligarh Muslim University in 1920.', '{"1": "Lucknow is known for the Nadwat-ul-Ulama and the 1916 pact.", "2": "Deoband is known for the Darul Uloom seminary, founded in 1866.", "3": "Lahore was not where Sir Syed founded his school."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Pakistan Studies', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('PST-0021', 'After 1857 and the Pakistan Movement', 'Sir Syed Ahmad Khan', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Aligarh Movement', 'Sir Syed Ahmad Khan''s pamphlet explaining the causes of the 1857 uprising is called:', '["Tahzib-ul-Akhlaq", "Asbab-e-Baghawat-e-Hind", "Musaddas-e-Hali", "Bang-e-Dra"]', 1, 'In Asbab-e-Baghawat-e-Hind (1859), Sir Syed argued that British policies, not Muslims alone, caused the revolt.', '{"0": "Tahzib-ul-Akhlaq was Sir Syed''s journal on social reform.", "2": "Musaddas-e-Hali is Altaf Hussain Hali''s poem on the rise and fall of Islam.", "3": "Bang-e-Dra is a collection of Allama Iqbal''s Urdu poetry."}'),
  ('PST-0022', 'After 1857 and the Pakistan Movement', 'Indian National Congress', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Indian National Congress', 'The Indian National Congress was founded in 1885 by:', '["Bal Gangadhar Tilak", "Lord Curzon", "Allan Octavian Hume", "Mahatma Gandhi"]', 2, 'A. O. Hume, a retired British civil servant, founded the Indian National Congress in Bombay in 1885.', '{"0": "Tilak was a Congress leader but not its founder.", "1": "Lord Curzon was the Viceroy who partitioned Bengal in 1905.", "3": "Gandhi led the Congress later, from about 1920."}'),
  ('PST-0023', 'After 1857 and the Pakistan Movement', 'Partition of Bengal', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Partition of Bengal', 'The Partition of Bengal, made in 1905, was cancelled in:', '["1909", "1916", "1911", "1906"]', 2, 'Lord Curzon divided Bengal in 1905; after Hindu agitation, the partition was annulled at the Delhi Durbar of 1911.', '{"0": "1909 brought the Minto-Morley Reforms.", "1": "1916 is the year of the Lucknow Pact.", "3": "1906 is the year the All-India Muslim League was founded."}'),
  ('PST-0024', 'After 1857 and the Pakistan Movement', 'All-India Muslim League', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Muslim League', 'The All-India Muslim League was founded on 30 December 1906 at:', '["Dhaka", "Lahore", "Lucknow", "Aligarh"]', 0, 'The League was founded at the All-India Muhammadan Educational Conference held in Dhaka in December 1906.', '{"1": "Lahore hosted the 1940 session that passed the Lahore Resolution.", "2": "Lucknow hosted the 1916 joint session with the Congress.", "3": "Aligarh was the seat of Sir Syed''s college, not the League''s founding session."}'),
  ('PST-0025', 'After 1857 and the Pakistan Movement', 'Simla Deputation', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Simla Deputation', 'The Simla Deputation of 1906, which asked the Viceroy for separate electorates for Muslims, was led by:', '["Quaid-e-Azam", "Allama Iqbal", "Sir Aga Khan III", "Nawab Salimullah"]', 2, 'On 1 October 1906, 35 Muslim leaders led by Sir Aga Khan III met Lord Minto at Simla.', '{"0": "Jinnah was then in the Congress; he joined the League in 1913.", "1": "Iqbal was still a student in Europe in 1906.", "3": "Nawab Salimullah hosted the League''s founding session in Dhaka."}'),
  ('PST-0026', 'After 1857 and the Pakistan Movement', 'Constitutional reforms', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Minto-Morley Reforms', 'Separate electorates for Muslims were first accepted in law by the:', '["Indian Councils Act 1892", "Montagu-Chelmsford Reforms (1919)", "Government of India Act 1935", "Minto-Morley Reforms (1909)"]', 3, 'The Indian Councils Act 1909, known as the Minto-Morley Reforms, gave Muslims separate electorates.', '{"0": "The 1892 Act had no separate electorates.", "1": "The 1919 reforms continued separate electorates already granted.", "2": "The 1935 Act kept separate electorates but did not introduce them."}'),
  ('PST-0027', 'After 1857 and the Pakistan Movement', 'Lucknow Pact', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Lucknow Pact', 'The Lucknow Pact between the Muslim League and the Congress was signed in:', '["1940", "1929", "1916", "1906"]', 2, 'In 1916 the Congress accepted separate electorates for Muslims in the Lucknow Pact, brought about largely by Jinnah.', '{"0": "1940 is the year of the Lahore Resolution.", "1": "1929 is the year of Jinnah''s Fourteen Points.", "3": "1906 is when the Muslim League was founded."}'),
  ('PST-0028', 'After 1857 and the Pakistan Movement', 'Khilafat Movement', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Khilafat Movement', 'The Khilafat Movement (1919-1924) was led in India mainly by:', '["Maulana Muhammad Ali Jauhar and Maulana Shaukat Ali", "Chaudhry Rahmat Ali", "Liaquat Ali Khan", "Sir Syed Ahmad Khan"]', 0, 'The Ali Brothers led the movement to protect the Ottoman Caliphate after the First World War.', '{"1": "Rahmat Ali is known for coining the name ''Pakistan''.", "2": "Liaquat Ali Khan became prominent in the League in the 1930s.", "3": "Sir Syed died in 1898."}'),
  ('PST-0029', 'After 1857 and the Pakistan Movement', 'Fourteen Points', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Nehru Report and Fourteen Points', 'Quaid-e-Azam''s Fourteen Points (1929) were a reply to the:', '["Nehru Report", "Government of India Act 1935", "Simon Commission", "Cripps Mission"]', 0, 'The Nehru Report (1928) rejected separate electorates; Jinnah set out Muslim demands in his Fourteen Points in March 1929.', '{"1": "The Act came six years later.", "2": "The Simon Commission (1927) was boycotted, but the Fourteen Points answered the Nehru Report.", "3": "The Cripps Mission came in 1942."}'),
  ('PST-0030', 'After 1857 and the Pakistan Movement', 'Allahabad Address', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Allahabad Address', 'Allama Iqbal presented the idea of a separate Muslim state in the north-west of India in his address at Allahabad in:', '["1933", "1930", "1927", "1940"]', 1, 'Iqbal gave his presidential address to the Muslim League at Allahabad on 29 December 1930.', '{"0": "1933 is when Chaudhry Rahmat Ali''s pamphlet ''Now or Never'' appeared.", "2": "1927 is the year the Simon Commission was announced.", "3": "1940 is the year of the Lahore Resolution."}'),
  ('PST-0031', 'After 1857 and the Pakistan Movement', 'Name of Pakistan', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Name of Pakistan', 'The name ''Pakistan'' was first proposed by:', '["Chaudhry Rahmat Ali", "A. K. Fazlul Haq", "Quaid-e-Azam", "Allama Iqbal"]', 0, 'Chaudhry Rahmat Ali used the name in his 1933 pamphlet ''Now or Never'', written at Cambridge.', '{"1": "Fazlul Haq moved the Lahore Resolution in 1940.", "2": "Jinnah led the movement but did not coin the name.", "3": "Iqbal proposed a Muslim state but not the name."}'),
  ('PST-0032', 'After 1857 and the Pakistan Movement', 'Round Table Conferences', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Round Table Conferences', 'The three Round Table Conferences (1930-1932) on India''s constitutional future were held in:', '["Simla", "Delhi", "London", "Lucknow"]', 2, 'The British government held the Round Table Conferences in London between 1930 and 1932.', '{"0": "Simla hosted the 1945 Simla Conference.", "1": "The conferences were held in Britain, not India.", "3": "Lucknow hosted the 1916 pact, not these conferences."}'),
  ('PST-0033', 'After 1857 and the Pakistan Movement', 'Day of Deliverance', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Congress rule 1937-39', 'Muslims observed the ''Day of Deliverance'' on 22 December 1939 to mark the end of:', '["Congress ministries in the provinces", "the Khilafat Movement", "the Second World War", "British rule in India"]', 0, 'Jinnah called for the Day of Deliverance after the Congress ministries (1937-1939) resigned.', '{"1": "The Khilafat Movement ended in 1924.", "2": "The war had only begun in September 1939.", "3": "British rule lasted until 1947."}'),
  ('PST-0034', 'After 1857 and the Pakistan Movement', 'Lahore Resolution', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Lahore Resolution', 'The Lahore Resolution of 23 March 1940 was moved by:', '["Quaid-e-Azam", "Chaudhry Khaliquzzaman", "A. K. Fazlul Haq", "Liaquat Ali Khan"]', 2, 'A. K. Fazlul Haq, Chief Minister of Bengal, moved the resolution at Minto Park (now Iqbal Park), Lahore.', '{"0": "Jinnah presided over the session.", "1": "Khaliquzzaman seconded the resolution; he did not move it.", "3": "Liaquat Ali Khan later moved the Objectives Resolution in 1949."}'),
  ('PST-0035', 'After 1857 and the Pakistan Movement', 'Lahore Resolution', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Lahore Resolution', 'Minar-e-Pakistan stands at the place where the Lahore Resolution was passed. That ground was then called:', '["Company Bagh", "Lawrence Gardens", "Minto Park", "Mochi Gate ground"]', 2, 'Minto Park in Lahore was renamed Iqbal Park; Minar-e-Pakistan marks the 1940 session.', '{"0": "Company Bagh in Rawalpindi is now Liaquat Bagh.", "1": "Lawrence Gardens is now Bagh-e-Jinnah.", "3": "Mochi Gate ground was a political rally site, but not this session."}'),
  ('PST-0036', 'After 1857 and the Pakistan Movement', 'Cabinet Mission', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Cabinet Mission Plan', 'The Muslim League called ''Direct Action Day'' on 16 August 1946 after the failure of the:', '["Simla Conference", "Cripps Mission", "3 June Plan", "Cabinet Mission Plan"]', 3, 'The League withdrew its acceptance of the Cabinet Mission Plan (1946) and called for Direct Action to press for Pakistan.', '{"0": "The Simla Conference failed in 1945.", "1": "The Cripps Mission failed in 1942.", "2": "The 3 June Plan came in 1947 and was accepted."}'),
  ('PST-0037', 'After 1857 and the Pakistan Movement', 'Independence', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), 3 June Plan', 'The plan for dividing British India into India and Pakistan, announced on 3 June 1947, was made by:', '["Lord Mountbatten", "Sir Cyril Radcliffe", "Lord Wavell", "Lord Linlithgow"]', 0, 'Lord Mountbatten, the last Viceroy, announced the partition plan on 3 June 1947.', '{"1": "Radcliffe drew the boundary lines after the plan.", "2": "Wavell was replaced by Mountbatten in March 1947.", "3": "Linlithgow was Viceroy from 1936 to 1943."}'),
  ('PST-0038', 'After 1857 and the Pakistan Movement', 'Independence', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Radcliffe Award', 'The boundary between India and Pakistan in Punjab and Bengal was drawn by a commission headed by:', '["Sir Cyril Radcliffe", "Sir Stafford Cripps", "Lord Mountbatten", "Lord Pethick-Lawrence"]', 0, 'Sir Cyril Radcliffe chaired both boundary commissions; his award was announced on 17 August 1947.', '{"1": "Cripps led the 1942 mission and was part of the 1946 Cabinet Mission.", "2": "Mountbatten was the Viceroy; he did not chair the boundary commissions.", "3": "Pethick-Lawrence led the 1946 Cabinet Mission."}'),
  ('PST-0039', 'After 1857 and the Pakistan Movement', 'Quaid-e-Azam', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Quaid-e-Azam', 'Quaid-e-Azam Muhammad Ali Jinnah was born on 25 December 1876 in:', '["Ziarat", "Lahore", "Bombay", "Karachi"]', 3, 'Jinnah was born in Karachi (Wazir Mansion) and is buried there at the Mazar-e-Quaid.', '{"0": "Ziarat is where he spent his last weeks in 1948.", "1": "Lahore was not his birthplace.", "2": "Jinnah practised law in Bombay but was born in Karachi."}'),
  ('PST-0040', 'After 1857 and the Pakistan Movement', 'Quaid-e-Azam', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Quaid-e-Azam', 'Muhammad Ali Jinnah joined the All-India Muslim League in:', '["1920", "1913", "1934", "1906"]', 1, 'Jinnah joined the League in 1913 while still a member of the Congress.', '{"0": "In 1920 he left the Congress, but he had joined the League years earlier.", "2": "In 1934 he returned from England to lead the League.", "3": "He was not among the founders in 1906; he was in the Congress."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Pakistan Studies', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('PST-0041', 'Pakistan since 1947', 'First government', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Early years of Pakistan', 'Who was the first Prime Minister of Pakistan?', '["Quaid-e-Azam", "Liaquat Ali Khan", "Muhammad Ali Bogra", "Khawaja Nazimuddin"]', 1, 'Liaquat Ali Khan was Prime Minister from August 1947 until he was assassinated in October 1951.', '{"0": "Jinnah was the first Governor-General, not Prime Minister.", "2": "Bogra became Prime Minister in 1953.", "3": "Nazimuddin was the second Governor-General and the second Prime Minister."}'),
  ('PST-0042', 'Pakistan since 1947', 'First government', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Early years of Pakistan', 'Liaquat Ali Khan was assassinated in 1951 while addressing a public meeting in:', '["Karachi", "Rawalpindi", "Dhaka", "Lahore"]', 1, 'He was shot at Company Bagh, Rawalpindi, on 16 October 1951; the park is now Liaquat Bagh.', '{"0": "Karachi was the capital, but the assassination took place elsewhere.", "2": "Dhaka was the capital of East Bengal.", "3": "Lahore was not where he was killed."}'),
  ('PST-0043', 'Pakistan since 1947', 'First government', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Early years of Pakistan', 'After Quaid-e-Azam''s death in 1948, who became Governor-General of Pakistan?', '["Liaquat Ali Khan", "Ghulam Muhammad", "Iskander Mirza", "Khawaja Nazimuddin"]', 3, 'Khawaja Nazimuddin, Chief Minister of East Bengal, became the second Governor-General in September 1948.', '{"0": "Liaquat stayed Prime Minister.", "1": "Ghulam Muhammad became Governor-General in 1951.", "2": "Mirza was the last Governor-General and first President (1956)."}'),
  ('PST-0044', 'Pakistan since 1947', 'Capital', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Capital of Pakistan', 'What was the capital of Pakistan before Islamabad?', '["Dhaka", "Lahore", "Karachi", "Rawalpindi"]', 2, 'Karachi was the first capital. The government decided in 1959 to build Islamabad, using Rawalpindi meanwhile.', '{"0": "Dhaka was the capital of East Pakistan.", "1": "Lahore is the capital of Punjab.", "3": "Rawalpindi was the interim capital while Islamabad was built, but the first capital was Karachi."}'),
  ('PST-0045', 'Pakistan since 1947', 'Objectives Resolution', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Constitution of Pakistan 1973, Article 2A and Annex', 'The Objectives Resolution was passed by the Constituent Assembly on:', '["14 August 1973", "23 March 1956", "12 March 1949", "23 March 1940"]', 2, 'Moved by Liaquat Ali Khan, the Objectives Resolution was passed on 12 March 1949. It is now Article 2A of the Constitution.', '{"0": "14 August 1973 is when the present Constitution came into force.", "1": "23 March 1956 is when the first Constitution came into force.", "3": "23 March 1940 is the Lahore Resolution."}'),
  ('PST-0046', 'Pakistan since 1947', 'Martial law', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Ayub era', 'Pakistan''s first nationwide martial law was imposed in:', '["March 1969", "July 1977", "October 1999", "October 1958"]', 3, 'President Iskander Mirza declared martial law on 7 October 1958 with General Ayub Khan as Chief Martial Law Administrator.', '{"0": "In March 1969 Yahya Khan took over from Ayub Khan.", "1": "July 1977 was General Zia-ul-Haq''s martial law.", "2": "In October 1999 General Musharraf took power, without formal martial law."}'),
  ('PST-0047', 'Pakistan since 1947', 'Indus Waters Treaty', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Indus Waters Treaty 1960, World Bank', 'The Indus Waters Treaty of 1960 between Pakistan and India was brokered by the:', '["Commonwealth", "Soviet Union", "United Nations", "World Bank"]', 3, 'Ayub Khan and Jawaharlal Nehru signed the treaty in Karachi in September 1960 under World Bank mediation.', '{"0": "The Commonwealth had no role in the treaty.", "1": "The Soviet Union brokered the Tashkent Declaration in 1966.", "2": "The UN dealt with Kashmir, but this treaty was the World Bank''s."}'),
  ('PST-0048', 'Pakistan since 1947', '1965 war', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), 1965 war', 'The Tashkent Declaration of January 1966, after the 1965 war, was signed with the help of the:', '["Soviet Union", "China", "United Kingdom", "United States"]', 0, 'Soviet Premier Kosygin hosted Ayub Khan and Lal Bahadur Shastri at Tashkent (now in Uzbekistan).', '{"1": "China backed Pakistan but did not mediate.", "2": "Britain did not host the talks.", "3": "The US was not the mediator at Tashkent."}'),
  ('PST-0049', 'Pakistan since 1947', 'One Unit', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), One Unit', 'The One Unit scheme merged the provinces of West Pakistan into a single province from 1955 until:', '["1962", "1958", "1970", "1973"]', 2, 'One Unit was created in 1955 and dissolved by Yahya Khan on 1 July 1970, restoring the four provinces.', '{"0": "The 1962 Constitution kept One Unit.", "1": "1958 saw martial law, but One Unit continued.", "3": "One Unit had already ended before the 1973 Constitution."}'),
  ('PST-0050', 'Pakistan since 1947', '1971', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Separation of East Pakistan', 'East Pakistan became Bangladesh on:', '["2 July 1972", "7 December 1970", "16 December 1971", "26 March 1971"]', 2, 'The war ended with the surrender at Dhaka on 16 December 1971.', '{"0": "2 July 1972 is the Simla Agreement.", "1": "7 December 1970 was the general election.", "3": "Bangladesh marks 26 March as its independence day, but the war ended in December."}'),
  ('PST-0051', 'Pakistan since 1947', 'Simla Agreement', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Simla Agreement', 'The Simla Agreement of 1972 was signed by Zulfikar Ali Bhutto and:', '["Rajiv Gandhi", "Indira Gandhi", "Jawaharlal Nehru", "Lal Bahadur Shastri"]', 1, 'The agreement (2 July 1972) turned the Kashmir ceasefire line into the Line of Control.', '{"0": "Rajiv Gandhi was Prime Minister from 1984.", "2": "Nehru died in 1964.", "3": "Shastri signed the Tashkent Declaration in 1966."}'),
  ('PST-0052', 'Pakistan since 1947', 'Nuclear tests', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Nuclear programme', 'Pakistan conducted its nuclear tests on 28 May 1998 in the hills of:', '["Kahuta, Punjab", "Thar, Sindh", "Kharan, Balochistan", "Chagai, Balochistan"]', 3, 'The tests of 28 May 1998 were in the Ras Koh hills of Chagai district; the day is marked as Youm-e-Takbeer.', '{"0": "Kahuta is home to a research laboratory, not the test site.", "1": "Thar is known for its coal field.", "2": "Kharan was the site of a further test on 30 May 1998, not 28 May."}'),
  ('PST-0053', 'Pakistan since 1947', 'Gwadar', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Gwadar', 'Pakistan bought Gwadar from Muscat and Oman in:', '["1971", "1947", "1958", "1965"]', 2, 'Gwadar became part of Pakistan on 8 September 1958 after it was bought from the Sultan of Muscat and Oman.', '{"0": "1971 is the year of East Pakistan''s separation.", "1": "Gwadar was still under Oman at independence.", "3": "By 1965 Gwadar was already part of Pakistan."}'),
  ('PST-0054', 'Pakistan since 1947', 'National symbols', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Government of Pakistan, National Anthem', 'The words of Pakistan''s national anthem were written by:', '["Allama Iqbal", "Hafeez Jalandhari", "Ahmed G. Chagla", "Faiz Ahmad Faiz"]', 1, 'Hafeez Jalandhari wrote the words; Ahmed Ghulamali Chagla composed the tune. The anthem was approved in 1954.', '{"0": "Iqbal wrote ''Tarana-e-Milli'', not the national anthem.", "2": "Chagla composed the music, not the words.", "3": "Faiz was a famous poet but did not write the anthem."}'),
  ('PST-0055', 'Pakistan since 1947', 'Judiciary', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Supreme Court of Pakistan, former Chief Justices', 'Who was the first Chief Justice of Pakistan?', '["Muhammad Shahabuddin", "Sir Abdul Rashid", "A. R. Cornelius", "Muhammad Munir"]', 1, 'Mian Sir Abdul Rashid headed the Federal Court from 1949 to 1954.', '{"0": "Justice Shahabuddin was Chief Justice briefly in 1960.", "2": "Justice Cornelius was Chief Justice from 1960 to 1968.", "3": "Justice Munir was the second, known for the 1955 Tamizuddin case."}'),
  ('PST-0056', 'Constitutions of Pakistan', '1956 Constitution', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Constitution of 1956', 'Pakistan was first named the ''Islamic Republic of Pakistan'' in the Constitution of:', '["1973", "1949", "1962", "1956"]', 3, 'The 1956 Constitution, in force from 23 March 1956, made Pakistan an Islamic Republic.', '{"0": "The 1973 Constitution kept the name already used in 1956.", "1": "1949 is the Objectives Resolution, not a constitution.", "2": "The 1962 Constitution first called the country the ''Republic of Pakistan''."}'),
  ('PST-0057', 'Constitutions of Pakistan', '1962 Constitution', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Constitution of 1962', 'The 1962 Constitution of Pakistan set up which system of government?', '["Confederal", "Parliamentary", "Presidential", "Monarchy"]', 2, 'Ayub Khan''s 1962 Constitution gave executive power to an indirectly elected President.', '{"0": "Pakistan has never had a confederation.", "1": "The 1956 and 1973 Constitutions are parliamentary.", "3": "Pakistan''s head of state has always been elected."}'),
  ('PST-0058', 'Constitutions of Pakistan', '1973 Constitution', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Constitution of Pakistan 1973, preamble and history', 'The present Constitution of Pakistan came into force on:', '["8 June 1962", "23 March 1956", "14 August 1973", "10 April 1973"]', 2, 'The National Assembly passed the Constitution on 10 April 1973; it came into force on 14 August 1973.', '{"0": "8 June 1962 is when the second Constitution came into force.", "1": "23 March 1956 is when the first Constitution came into force.", "3": "10 April 1973 is when the National Assembly passed it."}'),
  ('PST-0059', 'Constitutions of Pakistan', '1973 Constitution', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Constitution of Pakistan 1973, Articles 1 and 91', 'Under the Constitution of 1973, Pakistan has which system of government?', '["Federal parliamentary", "Federal presidential", "Unitary presidential", "Unitary parliamentary"]', 0, 'The 1973 Constitution makes Pakistan a federal republic with a Prime Minister answerable to the National Assembly.', '{"1": "That was the 1962 system.", "2": "Pakistan is neither unitary nor presidential.", "3": "Pakistan is a federation of provinces, so not unitary."}'),
  ('PST-0060', 'Constitutions of Pakistan', '1973 Constitution', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Constitution of Pakistan 1973, Article 41', 'Under Article 41 of the Constitution, a person must be at least how old to be elected President of Pakistan?', '["30 years", "45 years", "40 years", "25 years"]', 1, 'Article 41(2): the President must be a Muslim of not less than 45 years who is qualified to be a member of the National Assembly.', '{"0": "30 is the minimum age for the Senate (Article 62).", "2": "40 is the age for the President in some other countries, not Pakistan.", "3": "25 is the minimum age for the National Assembly (Article 62)."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Pakistan Studies', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('PST-0061', 'Constitutions of Pakistan', '1973 Constitution', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Constitution of Pakistan 1973, Article 49', 'When the office of President falls vacant, who acts as President under the Constitution?', '["The Chairman of the Senate", "The Prime Minister", "The Speaker of the National Assembly", "The Chief Justice of Pakistan"]', 0, 'Article 49: the Chairman of the Senate, or if he cannot, the Speaker of the National Assembly, acts as President.', '{"1": "The Prime Minister is head of government, not acting head of state.", "2": "The Speaker acts only if the Chairman of the Senate is unavailable.", "3": "The Chief Justice administers the oath; he does not act as President."}'),
  ('PST-0062', 'Constitutions of Pakistan', 'Amendments', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Constitution (Eighteenth Amendment) Act 2010', 'Which constitutional amendment, passed in 2010, removed the President''s power to dissolve the National Assembly at his discretion and gave more powers to the provinces?', '["Eighth Amendment", "Twenty-first Amendment", "Eighteenth Amendment", "Thirteenth Amendment"]', 2, 'The Eighteenth Amendment (April 2010) repealed Article 58(2)(b), abolished the Concurrent List and renamed NWFP as Khyber Pakhtunkhwa.', '{"0": "The Eighth Amendment (1985) gave the President that power under Article 58(2)(b).", "1": "The Twenty-first Amendment (2015) set up military courts.", "3": "The Thirteenth Amendment (1997) removed the power once, but it was restored in 2003."}'),
  ('PST-0063', 'Constitutions of Pakistan', 'Amendments', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Constitution (Eighteenth Amendment) Act 2010', 'The North-West Frontier Province was renamed Khyber Pakhtunkhwa by the:', '["Eighteenth Amendment (2010)", "Twenty-fifth Amendment (2018)", "Seventeenth Amendment (2003)", "Eighth Amendment (1985)"]', 0, 'The Eighteenth Amendment changed the province''s name in Article 1 of the Constitution.', '{"1": "The Twenty-fifth Amendment merged FATA into the province.", "2": "The Seventeenth Amendment dealt with President Musharraf''s powers.", "3": "The Eighth Amendment strengthened the President."}'),
  ('PST-0064', 'Constitutions of Pakistan', 'Amendments', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Constitution (Twenty-fifth Amendment) Act 2018', 'FATA (the Federally Administered Tribal Areas) was merged into Khyber Pakhtunkhwa by the:', '["Eighteenth Amendment (2010)", "Twenty-first Amendment (2015)", "Twenty-fifth Amendment (2018)", "First Amendment (1974)"]', 2, 'The Twenty-fifth Amendment (May 2018) removed FATA as a separate territory and merged it into Khyber Pakhtunkhwa.', '{"0": "The Eighteenth Amendment renamed NWFP but kept FATA separate.", "1": "The Twenty-first Amendment set up military courts.", "3": "The First Amendment recognised Bangladesh."}'),
  ('PST-0065', 'Constitutions of Pakistan', '1973 Constitution', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Constitution of Pakistan 1973, Article 251', 'Under Article 251 of the Constitution, the national language of Pakistan is:', '["Urdu", "Punjabi", "English", "Arabic"]', 0, 'Article 251(1): ''The National language of Pakistan is Urdu.''', '{"1": "Punjabi is the most widely spoken mother tongue but is not the national language.", "2": "English may be used for official purposes until arrangements are made for Urdu.", "3": "Arabic is to be taught under Article 31, but it is not the national language."}'),
  ('PST-0066', 'Geography of Pakistan', 'Mountains', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Physical geography', 'The highest mountain in Pakistan, and the second highest in the world, is:', '["Gasherbrum I", "K2", "Nanga Parbat", "Tirich Mir"]', 1, 'K2 (8,611 m), also called Mount Godwin-Austen, is in the Karakoram range in Gilgit-Baltistan.', '{"0": "Gasherbrum I (8,080 m) is lower than K2.", "2": "Nanga Parbat (8,126 m) is the ninth highest in the world.", "3": "Tirich Mir is the highest peak of the Hindu Kush."}'),
  ('PST-0067', 'Geography of Pakistan', 'Mountains', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Physical geography', 'Tirich Mir, the highest peak of the Hindu Kush, is in which district?', '["Skardu", "Chitral", "Hunza", "Swat"]', 1, 'Tirich Mir (about 7,700 m) rises in Chitral, Khyber Pakhtunkhwa.', '{"0": "Skardu is the gateway to the Karakoram peaks such as K2.", "2": "Hunza lies in the Karakoram, with peaks such as Rakaposhi.", "3": "Swat has peaks such as Falak Sar but not Tirich Mir."}'),
  ('PST-0068', 'Geography of Pakistan', 'Rivers', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Rivers of Pakistan', 'The longest river of Pakistan is the:', '["Jhelum", "Indus", "Chenab", "Kabul"]', 1, 'The Indus rises in Tibet, flows through Gilgit-Baltistan, Khyber Pakhtunkhwa, Punjab and Sindh, and enters the Arabian Sea.', '{"0": "The Jhelum is a tributary of the Chenab, which joins the Indus.", "2": "The Chenab is a tributary that joins the Indus via the Panjnad.", "3": "The Kabul River joins the Indus near Attock."}'),
  ('PST-0069', 'Geography of Pakistan', 'Rivers', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Indus Waters Treaty 1960, Articles II and III', 'Under the Indus Waters Treaty, the three ''western rivers'' given to Pakistan are:', '["Ravi, Sutlej and Beas", "Jhelum, Chenab and Ravi", "Indus, Ravi and Sutlej", "Indus, Jhelum and Chenab"]', 3, 'The treaty gave Pakistan the western rivers (Indus, Jhelum, Chenab) and India the eastern rivers (Ravi, Sutlej, Beas).', '{"0": "These are the eastern rivers, given to India.", "1": "The Ravi is an eastern river.", "2": "Ravi and Sutlej are eastern rivers."}'),
  ('PST-0070', 'Geography of Pakistan', 'Rivers', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Indus Waters Treaty: Baglihar neutral expert decision, 2007', 'India''s Baglihar Dam, which Pakistan took to a neutral expert under the Indus Waters Treaty, is on the river:', '["Jhelum", "Neelum (Kishanganga)", "Chenab", "Ravi"]', 2, 'The Baglihar hydroelectric project is on the Chenab in Indian-held Jammu; a neutral expert gave a ruling in 2007.', '{"0": "India''s Wular barrage project is on the Jhelum.", "1": "The Kishanganga project is on the Neelum.", "3": "The Ravi is an eastern river, so its use by India was never disputed."}'),
  ('PST-0071', 'Geography of Pakistan', 'Dams', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: WAPDA, Tarbela Dam', 'Tarbela Dam is built on the river:', '["Indus", "Swat", "Kabul", "Jhelum"]', 0, 'Tarbela, in Haripur district, Khyber Pakhtunkhwa, is one of the largest earth-filled dams in the world.', '{"1": "The Swat River has smaller dams, such as Munda (Mohmand), not Tarbela.", "2": "Warsak Dam is on the Kabul River.", "3": "Mangla Dam is on the Jhelum."}'),
  ('PST-0072', 'Geography of Pakistan', 'Dams', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: WAPDA, Mangla Dam', 'Mangla Dam is built on the river:', '["Jhelum", "Kabul", "Indus", "Chenab"]', 0, 'Mangla Dam, completed in 1967, is on the Jhelum in Mirpur, Azad Kashmir.', '{"1": "Warsak Dam is on the Kabul River.", "2": "Tarbela Dam is on the Indus.", "3": "The Chenab has barrages (such as Marala) but not Mangla."}'),
  ('PST-0073', 'Geography of Pakistan', 'Provinces', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Bureau of Statistics, area by province', 'Which is the largest province of Pakistan by area?', '["Balochistan", "Khyber Pakhtunkhwa", "Punjab", "Sindh"]', 0, 'Balochistan covers about 44 per cent of Pakistan''s land area.', '{"1": "Khyber Pakhtunkhwa is the smallest of the four provinces by area.", "2": "Punjab has the most people but less area.", "3": "Sindh is smaller than both Balochistan and Punjab."}'),
  ('PST-0074', 'Geography of Pakistan', 'Passes', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Mountain passes', 'The Khunjerab Pass connects Pakistan with:', '["Tajikistan", "Afghanistan", "China", "India"]', 2, 'The Karakoram Highway crosses into China''s Xinjiang over the Khunjerab Pass, about 4,700 m high.', '{"0": "The Wakhan strip separates Pakistan from Tajikistan.", "1": "The Khyber Pass is the main route to Afghanistan.", "3": "There is no road pass to India in that region."}'),
  ('PST-0075', 'Geography of Pakistan', 'Passes', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Mountain passes', 'The Khyber Pass links Peshawar with:', '["China", "Afghanistan", "Chitral", "Iran"]', 1, 'The Khyber Pass runs from near Peshawar to Torkham on the Afghan border.', '{"0": "The Khunjerab Pass links Pakistan with China.", "2": "Chitral is reached over the Lowari Pass.", "3": "The main crossing to Iran is at Taftan, Balochistan."}'),
  ('PST-0076', 'Geography of Pakistan', 'Passes', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Mountain passes', 'The Bolan Pass is in which province?', '["Khyber Pakhtunkhwa", "Gilgit-Baltistan", "Balochistan", "Sindh"]', 2, 'The Bolan Pass links Sibi with Quetta; the railway to Quetta runs through it.', '{"0": "The Khyber, Lowari and Kohat passes are here.", "1": "The Khunjerab Pass is here.", "3": "Sindh is plains and desert, with no major passes."}'),
  ('PST-0077', 'Geography of Pakistan', 'Deserts', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Deserts of Pakistan', 'The Cholistan Desert is in which province?', '["Khyber Pakhtunkhwa", "Punjab", "Sindh", "Balochistan"]', 1, 'Cholistan lies in southern Punjab, mostly in Bahawalpur district; it is the setting of the Cholistan Jeep Rally.', '{"0": "Khyber Pakhtunkhwa has no major desert.", "2": "Sindh has the Thar Desert.", "3": "Balochistan has the Kharan Desert."}'),
  ('PST-0078', 'Geography of Pakistan', 'Deserts', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Deserts of Pakistan', 'The Thal Desert lies between which two rivers?', '["Ravi and Sutlej", "Indus and Jhelum", "Chenab and Ravi", "Indus and Kabul"]', 1, 'The Thal lies in the Sindh Sagar Doab, between the Indus and the Jhelum, in Punjab.', '{"0": "The land between them is the Bari Doab.", "2": "The land between them is the Rechna Doab.", "3": "These rivers meet at Attock; there is no desert between them."}'),
  ('PST-0079', 'Geography of Pakistan', 'Borders', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Borders of Pakistan', 'The border between Pakistan and Afghanistan is called the:', '["McMahon Line", "Durand Line", "Line of Control", "Radcliffe Line"]', 1, 'Sir Mortimer Durand and the Afghan Amir Abdur Rahman agreed the line in 1893.', '{"0": "The McMahon Line is the border between India and China in the east.", "2": "The Line of Control divides Kashmir.", "3": "The Radcliffe Line is the 1947 border with India."}'),
  ('PST-0080', 'Geography of Pakistan', 'Borders', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Location of Pakistan', 'Which narrow strip of Afghan territory separates Pakistan from Tajikistan?', '["Kurram Valley", "Gomal Pass", "Wakhan Corridor", "Siachen"]', 2, 'The Wakhan Corridor in Afghanistan''s Badakhshan province lies between Chitral and Tajikistan.', '{"0": "The Kurram Valley is inside Pakistan.", "1": "The Gomal Pass is a pass on the Afghan border, not a strip of land.", "3": "Siachen is a glacier on the Kashmir front with India."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Pakistan Studies', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('PST-0081', 'Geography of Pakistan', 'Minerals', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Mineral Development Corporation, Khewra Salt Mine', 'The Khewra Salt Mine is in which mountain range?', '["Kirthar Range", "Sulaiman Range", "Margalla Hills", "Salt Range"]', 3, 'Khewra, in Jhelum district, is one of the oldest and largest salt mines in the world.', '{"0": "The Kirthar Range divides Sindh and Balochistan.", "1": "The Sulaiman Range runs along the Punjab-Balochistan border.", "2": "The Margalla Hills are near Islamabad."}'),
  ('PST-0082', 'Geography of Pakistan', 'Minerals', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Mineral resources', 'Pakistan''s largest natural gas field, discovered in 1952, is at:', '["Thar", "Mari", "Reko Diq", "Sui"]', 3, 'The Sui gas field in Dera Bugti, Balochistan, was found in 1952; ''Sui gas'' became the common name for piped gas.', '{"0": "Thar is known for coal.", "1": "Mari is a large gas field in Sindh, but Sui was found first and is the best known.", "2": "Reko Diq is known for copper and gold."}'),
  ('PST-0083', 'Geography of Pakistan', 'Minerals', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Mineral resources', 'Reko Diq in Chagai district is known for its deposits of:', '["Copper and gold", "Coal", "Rock salt", "Natural gas"]', 0, 'Reko Diq holds one of the world''s largest undeveloped copper-gold deposits.', '{"1": "The largest coal deposits are at Thar.", "2": "Rock salt is mined at Khewra.", "3": "Natural gas comes from Sui and Mari."}'),
  ('PST-0084', 'Geography of Pakistan', 'Minerals', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Mineral resources', 'Pakistan''s largest coal reserves are in:', '["Salt Range, Punjab", "Kohat, Khyber Pakhtunkhwa", "Thar, Sindh", "Chagai, Balochistan"]', 2, 'The Thar coalfield in Tharparkar, Sindh, holds most of Pakistan''s coal (lignite).', '{"0": "The Salt Range has some coal, but far less than Thar.", "1": "Kohat is known for gas and salt.", "3": "Chagai is known for copper and gold."}'),
  ('PST-0085', 'Geography of Pakistan', 'Cities', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Cities of Pakistan', 'Faisalabad was formerly known as:', '["Mintgumri", "Montgomery", "Campbellpur", "Lyallpur"]', 3, 'Lyallpur, named after Sir James Lyall, was renamed Faisalabad in honour of King Faisal of Saudi Arabia.', '{"0": "This is only a spelling of Montgomery, the old name of Sahiwal.", "1": "Montgomery is the old name of Sahiwal.", "2": "Campbellpur is the old name of Attock."}'),
  ('PST-0086', 'Geography of Pakistan', 'Cities', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Cities of Pakistan', 'Sahiwal was formerly called:', '["Montgomery", "Jacobabad", "Lyallpur", "Campbellpur"]', 0, 'Montgomery, named after Sir Robert Montgomery, was renamed Sahiwal in the 1960s.', '{"1": "Jacobabad still has its old name.", "2": "Lyallpur is the old name of Faisalabad.", "3": "Campbellpur is the old name of Attock."}'),
  ('PST-0087', 'Geography of Pakistan', 'Glaciers', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Physical geography', 'The Siachen, Baltoro and Biafo glaciers are in which mountain range?', '["Himalaya", "Sulaiman", "Hindu Kush", "Karakoram"]', 3, 'The Karakoram has some of the longest glaciers outside the polar regions.', '{"0": "Nanga Parbat is the main Himalayan peak in Pakistan.", "1": "The Sulaiman Range has no large glaciers.", "2": "The Hindu Kush is to the west, in Chitral."}'),
  ('PST-0088', 'Geography of Pakistan', 'Plains', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Physical geography', 'The Deosai Plains, one of the highest plateaus in the world, are in:', '["Balochistan", "Potohar, Punjab", "Gilgit-Baltistan", "Azad Kashmir"]', 2, 'Deosai National Park lies at about 4,100 m between Skardu and Astore.', '{"0": "Balochistan has a large but much lower plateau.", "1": "The Potohar Plateau is low and dry, near Rawalpindi.", "3": "Deosai lies just north of Azad Kashmir, in Gilgit-Baltistan."}'),
  ('PST-0089', 'Economy, resources and culture', 'Banking', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: State Bank of Pakistan, history', 'The State Bank of Pakistan was inaugurated by Quaid-e-Azam on:', '["23 March 1956", "11 September 1948", "1 July 1948", "14 August 1947"]', 2, 'Jinnah inaugurated the State Bank in Karachi on 1 July 1948, one of his last public engagements.', '{"0": "That is when the first Constitution came into force.", "1": "That is the day Quaid-e-Azam died.", "3": "Pakistan became independent then, but the State Bank opened later."}'),
  ('PST-0090', 'Economy, resources and culture', 'National symbols', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Government of Pakistan, national symbols', 'The national animal of Pakistan is the:', '["Chukar", "Markhor", "Indus river dolphin", "Snow leopard"]', 1, 'The markhor, a wild goat with spiral horns, is the national animal of Pakistan.', '{"0": "The chukar partridge is the national bird.", "2": "The Indus river dolphin is a rare mammal of the Indus, but not the national animal.", "3": "The snow leopard lives in Pakistan''s north but is not the national animal."}'),
  ('PST-0091', 'Economy, resources and culture', 'National symbols', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Government of Pakistan, national symbols', 'The national flower of Pakistan is the:', '["Lotus", "Tulip", "Jasmine", "Rose"]', 2, 'Jasmine (chambeli) is the national flower of Pakistan.', '{"0": "The lotus is the national flower of India.", "1": "The tulip is linked to Turkey and the Netherlands.", "3": "The rose is a national flower of other countries."}'),
  ('PST-0092', 'Economy, resources and culture', 'National symbols', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Government of Pakistan, national symbols', 'The national tree of Pakistan is the:', '["Neem", "Deodar", "Chinar", "Banyan"]', 1, 'The deodar (Cedrus deodara), a Himalayan cedar, is the national tree.', '{"0": "The neem is common in the plains but is not the national tree.", "2": "The chinar is common in Kashmir but is not the national tree.", "3": "The banyan is the national tree of India."}'),
  ('PST-0093', 'Economy, resources and culture', 'Agriculture', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Economic Survey, Agriculture chapter', 'Pakistan''s most important cash crop, the base of its textile industry, is:', '["Rice", "Wheat", "Cotton", "Sugarcane"]', 2, 'Cotton supplies Pakistan''s textile sector, which earns the largest share of export income.', '{"0": "Rice is a major export crop but not the base of the textile industry.", "1": "Wheat is the main food crop.", "3": "Sugarcane feeds the sugar industry."}'),
  ('PST-0094', 'Economy, resources and culture', 'Literature', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Regional literature', 'Shah Jo Risalo is the poetry of:', '["Bulleh Shah", "Rahman Baba", "Shah Abdul Latif Bhittai", "Sachal Sarmast"]', 2, 'Shah Abdul Latif Bhittai (1689-1752), buried at Bhit Shah, is the greatest poet of Sindhi.', '{"0": "Bulleh Shah wrote in Punjabi, at Kasur.", "1": "Rahman Baba wrote in Pashto.", "3": "Sachal Sarmast was another Sindhi Sufi poet, of Khairpur."}'),
  ('PST-0095', 'Economy, resources and culture', 'Literature', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Regional literature', 'Heer, the famous Punjabi verse romance, was written by:', '["Khushal Khan Khattak", "Bulleh Shah", "Mian Muhammad Bakhsh", "Waris Shah"]', 3, 'Waris Shah completed Heer in the 18th century; he is buried at Jandiala Sher Khan.', '{"0": "Khushal Khan Khattak was a Pashto poet.", "1": "Bulleh Shah wrote Sufi kafis, not Heer.", "2": "Mian Muhammad Bakhsh wrote Saif-ul-Malook."}'),
  ('PST-0096', 'Economy, resources and culture', 'Literature', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Regional literature', 'Khushal Khan Khattak is a famous poet of which language?', '["Pashto", "Punjabi", "Sindhi", "Balochi"]', 0, 'Khushal Khan Khattak (1613-1689), warrior and poet, is called the national poet of the Pashtuns.', '{"1": "Punjabi''s classical poets include Waris Shah and Bulleh Shah.", "2": "Sindhi''s great poet is Shah Abdul Latif Bhittai.", "3": "Balochi''s classical poet is Jam Durrak."}'),
  ('PST-0097', 'Economy, resources and culture', 'Space', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: SUPARCO, satellite history', 'Pakistan''s first satellite, launched in 1990, was named:', '["PRSS-1", "iCube-Qamar", "PakSat-1R", "Badr-1"]', 3, 'SUPARCO''s Badr-1 was launched from China on 16 July 1990.', '{"0": "PRSS-1 is a remote-sensing satellite launched in 2018.", "1": "iCube-Qamar went to the Moon with China''s Chang''e-6 in 2024.", "2": "PakSat-1R is a communications satellite launched in 2011."}'),
  ('PST-0098', 'Economy, resources and culture', 'Heritage', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: UNESCO World Heritage List, Pakistan', 'Which of these is NOT a UNESCO World Heritage Site in Pakistan?', '["Makli Necropolis, Thatta", "Rohtas Fort", "Taxila", "Minar-e-Pakistan"]', 3, 'Pakistan''s World Heritage Sites are Mohenjo-daro, Taxila, Takht-i-Bahi, Lahore Fort and Shalimar Gardens, Makli and Rohtas Fort. Minar-e-Pakistan is a national monument, not on the list.', '{"0": "The Makli monuments were inscribed in 1981.", "1": "Rohtas Fort was inscribed in 1997.", "2": "Taxila was inscribed in 1980."}'),
  ('PST-0099', 'Economy, resources and culture', 'CPEC', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: CPEC Authority, Government of Pakistan', 'The China-Pakistan Economic Corridor (CPEC) links Gwadar port with which region of China?', '["Guangdong (Guangzhou)", "Tibet (Lhasa)", "Xinjiang (Kashgar)", "Yunnan (Kunming)"]', 2, 'CPEC runs from Gwadar on the Arabian Sea to Kashgar in Xinjiang, crossing at Khunjerab.', '{"0": "Guangdong is on China''s south coast.", "1": "There is no road link from Pakistan to Lhasa.", "3": "Yunnan borders Myanmar, not Pakistan."}'),
  ('PST-0100', 'Foreign relations', 'United Nations', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Pakistan and the UN', 'Which country voted against Pakistan''s admission to the United Nations in 1947?', '["India", "Iran", "China", "Afghanistan"]', 3, 'Afghanistan cast the only vote against, citing its claim over Pashtun areas; it withdrew the objection weeks later. Pakistan joined on 30 September 1947.', '{"0": "India did not vote against Pakistan''s admission.", "1": "Iran was the first country to recognise Pakistan.", "2": "The People''s Republic was not yet a UN member in 1947."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Pakistan Studies', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('PST-0101', 'Foreign relations', 'Recognition', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Foreign policy', 'The first country to recognise Pakistan after independence was:', '["Turkey", "China", "Iran", "Saudi Arabia"]', 2, 'Iran was the first state to recognise Pakistan in August 1947.', '{"0": "Turkey recognised Pakistan early, but after Iran.", "1": "China and Pakistan set up relations in 1951.", "3": "Saudi Arabia is a close ally but was not the first."}'),
  ('PST-0102', 'Foreign relations', 'Alliances', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Foreign policy', 'Pakistan joined SEATO in 1954 and CENTO (the Baghdad Pact) in 1955, alliances led by the:', '["United States and United Kingdom", "Arab League", "Soviet Union", "Non-Aligned Movement"]', 0, 'Both were Western-backed Cold War alliances; Pakistan left SEATO in 1972-73 and CENTO in 1979.', '{"1": "The Arab League is an organisation of Arab states.", "2": "These pacts were meant to contain Soviet influence.", "3": "Pakistan joined the Non-Aligned Movement only in 1979, after leaving CENTO."}'),
  ('PST-0103', 'Foreign relations', 'Regional organisations', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Economic Cooperation Organization, history', 'The Regional Cooperation for Development (RCD), set up in 1964 by Pakistan, Iran and Turkey, became in 1985 the:', '["D-8", "Economic Cooperation Organization (ECO)", "SAARC", "Shanghai Cooperation Organisation"]', 1, 'RCD was renamed ECO in 1985; it grew to ten members after 1992, with its secretariat in Tehran.', '{"0": "The D-8 group was formed in 1997.", "2": "SAARC was also founded in 1985 but is a separate South Asian body.", "3": "The SCO was founded in 2001 and Pakistan joined in 2017."}'),
  ('PST-0104', 'Foreign relations', 'OIC', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: OIC, history of summits', 'The second summit of the Organisation of Islamic Cooperation (then Conference) was held in 1974 in:', '["Makkah", "Islamabad", "Rabat", "Lahore"]', 3, 'The Lahore summit of February 1974, hosted by Zulfikar Ali Bhutto, is also when Pakistan recognised Bangladesh.', '{"0": "Makkah and Taif hosted the third summit in 1981.", "1": "Islamabad has hosted OIC meetings, but not the 1974 summit.", "2": "Rabat hosted the first summit in 1969."}'),
  ('PST-0105', 'Foreign relations', 'China', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Studies (compulsory), Pakistan-China relations', 'Pakistan and China signed their boundary agreement in:', '["1978", "1951", "2015", "1963"]', 3, 'The Sino-Pakistan boundary agreement was signed on 2 March 1963.', '{"0": "1978 is when the Karakoram Highway opened.", "1": "1951 is when diplomatic relations began.", "2": "2015 is when CPEC was formally launched."}'),
  ('PST-0106', 'Foreign relations', 'SCO', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Shanghai Cooperation Organisation, member states', 'Pakistan became a full member of the Shanghai Cooperation Organisation in:', '["2022", "2005", "2001", "2017"]', 3, 'Pakistan and India both became full SCO members at the Astana summit in June 2017.', '{"0": "By 2022 Pakistan had been a member for five years.", "1": "In 2005 Pakistan became an observer.", "2": "2001 is when the SCO was founded, without Pakistan."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO bank_questions (bank, question_id, subject, chapter)
SELECT 'lat', id, subject, chapter FROM questions WHERE id LIKE 'PST-%';

INSERT INTO question_counters (prefix, n) VALUES ('PST', 106) ON CONFLICT (prefix) DO UPDATE SET n = max(n, 106);

-- LAT Islamiat: 92 original MCQs, ISL-0001 to ISL-0092 (HEC LAT Part I has 10 Islamiat MCQs).
-- Chapters: the Quran, hadith, the life of the Holy Prophet (PBUH), beliefs and worship, the Rightly Guided Caliphs,
-- prophets and companions, and Islamic law and society. Every key was checked against the Quran (verse given) or a
-- named hadith collection, or the standard Islamiat (compulsory) course; points on which schools of thought differ
-- are left out. Written for Markhor Prep, not copied from any book. questions.mdcat = 0; listed in the LAT bank.

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Islamiat', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('ISL-0001', 'The Quran', 'Structure of the Quran', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran, order of surahs', 'How many surahs are there in the Holy Quran?', '["110", "112", "116", "114"]', 3, 'The Holy Quran has 114 surahs, from Al-Fatiha to An-Nas.', '{"0": "110 is the number of one surah, An-Nasr, not the total.", "1": "112 is the number of Surah Al-Ikhlas.", "2": "The Quran has 114 surahs, not more."}'),
  ('ISL-0002', 'The Quran', 'Structure of the Quran', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran, divisions', 'The Holy Quran is divided into how many paras (juz)?', '["7", "30", "40", "114"]', 1, 'The Quran is divided into 30 equal parts (paras or ajza) for reading.', '{"0": "7 is the number of manzils, used for reciting the Quran in a week.", "2": "There are 30 paras, one for each night of Ramadan.", "3": "114 is the number of surahs."}'),
  ('ISL-0003', 'The Quran', 'Revelation', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Sahih al-Bukhari, Book of Revelation, hadith 3', 'The first verses of the Holy Quran were revealed in the Cave of:', '["Safa", "Hira", "Uhud", "Thawr"]', 1, 'The first revelation came in Cave Hira on Jabal al-Nur, near Makkah.', '{"0": "Safa is a hill at the Kaaba, used in Sa''i.", "2": "Uhud is a mountain near Madinah, site of the battle of 3 AH.", "3": "The Holy Prophet (PBUH) hid in Cave Thawr during the Hijrah."}'),
  ('ISL-0004', 'The Quran', 'Revelation', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran 96:1-5; Sahih al-Bukhari, hadith 3', 'The first verses revealed to the Holy Prophet (PBUH) are the opening verses of Surah:', '["Al-Muddaththir", "Al-Baqarah", "Al-Fatiha", "Al-Alaq"]', 3, 'The first revelation was ''Read in the name of your Lord who created'' (Al-Alaq 96:1-5).', '{"0": "Al-Muddaththir''s opening verses came after a pause in revelation.", "1": "Al-Baqarah is a Madinan surah.", "2": "Al-Fatiha is first in the order of the Quran, not of revelation."}'),
  ('ISL-0005', 'The Quran', 'Surahs', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran, Surah 2', 'The longest surah of the Holy Quran is:', '["Al-Baqarah", "Al-Kawthar", "Al-Imran", "An-Nisa"]', 0, 'Al-Baqarah has 286 verses, the most of any surah.', '{"1": "Al-Kawthar is the shortest surah, with 3 verses.", "2": "Al-Imran (200 verses) is the third surah and the second longest.", "3": "An-Nisa has 176 verses."}'),
  ('ISL-0006', 'The Quran', 'Surahs', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran, Surah 108', 'The shortest surah of the Holy Quran is:', '["An-Nas", "Al-Asr", "Al-Kawthar", "Al-Ikhlas"]', 2, 'Al-Kawthar (Surah 108) has three short verses and the fewest words of any surah.', '{"0": "An-Nas has 6 verses.", "1": "Al-Asr has 3 verses, but they are longer than Al-Kawthar''s.", "3": "Al-Ikhlas has 4 verses."}'),
  ('ISL-0007', 'The Quran', 'Surahs', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran, Surah 9', 'Which surah does not begin with ''Bismillah ir-Rahman ir-Rahim''?', '["Al-Fatiha", "An-Naml", "Yasin", "At-Tawbah"]', 3, 'Surah At-Tawbah (9) is the only surah without the Bismillah at its start.', '{"0": "Al-Fatiha begins with the Bismillah.", "1": "An-Naml has the Bismillah twice: at the start and in verse 30.", "2": "Yasin begins with the Bismillah."}'),
  ('ISL-0008', 'The Quran', 'Surahs', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran 27:30', 'In which surah does ''Bismillah ir-Rahman ir-Rahim'' appear twice?', '["Al-Fatiha", "Al-Baqarah", "At-Tawbah", "An-Naml"]', 3, 'An-Naml (27) opens with it and quotes it again in Prophet Sulaiman''s (AS) letter to the Queen of Sheba (27:30).', '{"0": "Al-Fatiha has it once, as its first verse.", "1": "Al-Baqarah has it once, at the start.", "2": "At-Tawbah has no Bismillah at its start."}'),
  ('ISL-0009', 'The Quran', 'Surahs', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran 2:255', 'Ayat al-Kursi is a verse of which surah?', '["Yasin", "Al-Imran", "Al-Mulk", "Al-Baqarah"]', 3, 'Ayat al-Kursi is verse 255 of Surah Al-Baqarah.', '{"0": "Yasin is called the heart of the Quran.", "1": "Al-Imran follows Al-Baqarah but does not contain Ayat al-Kursi.", "2": "Al-Mulk is recited for protection in the grave, but it does not contain Ayat al-Kursi."}'),
  ('ISL-0010', 'The Quran', 'Surahs', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Jami at-Tirmidhi, Book of the Virtues of the Quran', 'Which surah is called the ''heart of the Quran''?', '["Al-Fatiha", "Ar-Rahman", "Yasin", "Al-Ikhlas"]', 2, 'A narration in Jami at-Tirmidhi calls Surah Yasin the heart of the Quran.', '{"0": "Al-Fatiha is called Umm al-Kitab, the mother of the Book.", "1": "Ar-Rahman is known for its refrain about Allah''s favours.", "3": "Al-Ikhlas is said to equal a third of the Quran."}'),
  ('ISL-0011', 'The Quran', 'Surahs', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran, Surah 112', 'Which surah gives the most concise statement of Tauheed (the Oneness of Allah)?', '["Al-Kawthar", "Al-Ikhlas", "Al-Asr", "Al-Fatiha"]', 1, 'Al-Ikhlas (112): ''Say, He is Allah, the One... He neither begets nor is born, nor is there any equal to Him.''', '{"0": "Al-Kawthar is about the gift of Kawthar to the Holy Prophet (PBUH).", "2": "Al-Asr is about time and loss.", "3": "Al-Fatiha is a prayer for guidance."}'),
  ('ISL-0012', 'The Quran', 'Surahs', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran, Surah 19', 'The only surah named after a woman is:', '["An-Nisa", "Al-Mujadilah", "Maryam", "Al-Mumtahanah"]', 2, 'Surah Maryam (19) is named after Hazrat Maryam, mother of Prophet Isa (AS), who is also the only woman named in the Quran.', '{"0": "An-Nisa means ''The Women'' and is about women in general.", "1": "Al-Mujadilah refers to a woman but does not carry her name.", "3": "Al-Mumtahanah means ''the woman examined'', not a name."}'),
  ('ISL-0013', 'The Quran', 'Surahs', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran 4:11-12, 4:176', 'Which surah sets out the detailed shares of inheritance?', '["Al-Baqarah", "Al-Maidah", "An-Nisa", "An-Nur"]', 2, 'An-Nisa 4:11-12 and 4:176 set out the shares of heirs.', '{"0": "Al-Baqarah has rules on wills and divorce, but the shares are in An-Nisa.", "1": "Al-Maidah covers food, contracts and the hand-cutting penalty for theft.", "3": "An-Nur covers modesty and the penalty for false accusation."}'),
  ('ISL-0014', 'The Quran', 'Names in the Quran', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran 33:37', 'The only companion of the Holy Prophet (PBUH) mentioned by name in the Holy Quran is:', '["Hazrat Abu Bakr (RA)", "Hazrat Ali (RA)", "Hazrat Bilal (RA)", "Hazrat Zaid bin Harithah (RA)"]', 3, 'Surah Al-Ahzab 33:37 names Zaid, the Holy Prophet''s (PBUH) freed slave and adopted son.', '{"0": "Abu Bakr (RA) is referred to in the Cave verse (9:40) but not by name.", "1": "Ali (RA) is not named in the Quran.", "2": "Bilal (RA) is not named in the Quran."}'),
  ('ISL-0015', 'The Quran', 'Names in the Quran', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran 8:41', 'The Battle of Badr is called ''Yaum al-Furqan'' (the Day of Criterion) in Surah:', '["Al-Fath", "Al-Anfal", "Al-Ahzab", "Al-Imran"]', 1, 'Al-Anfal 8:41 refers to ''the Day of Criterion, the day the two forces met''.', '{"0": "Al-Fath is about the Treaty of Hudaybiyyah.", "2": "Al-Ahzab is about the Battle of the Trench.", "3": "Al-Imran discusses Badr and Uhud but does not use this name."}'),
  ('ISL-0016', 'The Quran', 'Compilation', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Sahih al-Bukhari, Book of the Virtues of the Quran, hadith 4986', 'The Holy Quran was first gathered into a single written copy during the caliphate of:', '["Hazrat Uthman (RA)", "Hazrat Umar (RA)", "Hazrat Ali (RA)", "Hazrat Abu Bakr (RA)"]', 3, 'After many huffaz were martyred at Yamamah, Abu Bakr (RA), on Umar''s (RA) advice, had Zaid bin Thabit (RA) gather the Quran into one copy.', '{"0": "Uthman (RA) had standard copies made and sent to the provinces, later.", "1": "Umar (RA) suggested the compilation but was not yet caliph.", "2": "Ali (RA) became caliph long after the compilation."}'),
  ('ISL-0017', 'The Quran', 'Compilation', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Sahih al-Bukhari, hadith 4987', 'Which caliph had standard copies of the Holy Quran made and sent to the main cities?', '["Hazrat Ali (RA)", "Hazrat Uthman (RA)", "Hazrat Umar (RA)", "Hazrat Abu Bakr (RA)"]', 1, 'Uthman (RA), called Jami-ul-Quran, had copies made from Hafsa''s (RA) manuscript so that all would recite one text.', '{"0": "Ali (RA) did not issue the standard copies.", "2": "Umar (RA) kept Abu Bakr''s copy, which passed to Hafsa (RA).", "3": "Abu Bakr (RA) had the first single copy gathered."}'),
  ('ISL-0018', 'The Quran', 'Revelation', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran 26:193', 'Which angel brought the revelation to the Holy Prophet (PBUH)?', '["Hazrat Israfil (AS)", "Hazrat Jibrail (AS)", "Hazrat Mikail (AS)", "Hazrat Izrail (AS)"]', 1, 'Jibrail (AS), called Ruh al-Amin (the trustworthy spirit), brought the Quran (Ash-Shu''ara 26:193).', '{"0": "Israfil (AS) will blow the trumpet on the Day of Judgement.", "2": "Mikail (AS) is linked with rain and provision.", "3": "Izrail (AS) is the angel of death."}'),
  ('ISL-0019', 'The Quran', 'Laylat al-Qadr', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran 2:185, 97:1', 'The Holy Quran says it was sent down on Laylat al-Qadr, which falls in the month of:', '["Muharram", "Rabi-ul-Awwal", "Ramadan", "Shaban"]', 2, 'Al-Qadr 97:1 and Al-Baqarah 2:185 together show the Quran was sent down on a night in Ramadan.', '{"0": "Muharram is the first month of the Islamic year.", "1": "Rabi-ul-Awwal is the month of the Holy Prophet''s (PBUH) birth.", "3": "Shaban comes before Ramadan."}'),
  ('ISL-0020', 'Hadith and Sunnah', 'Books of hadith', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Sahih al-Bukhari, introduction', 'Sahih al-Bukhari was compiled by:', '["Imam Muslim bin al-Hajjaj", "Imam Abu Dawud", "Imam Malik", "Imam Muhammad bin Ismail al-Bukhari"]', 3, 'Imam al-Bukhari (194-256 AH) compiled the Sahih, the most respected of the six books of hadith.', '{"0": "Imam Muslim compiled Sahih Muslim.", "1": "Imam Abu Dawud compiled the Sunan Abu Dawud.", "2": "Imam Malik compiled the Muwatta."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Islamiat', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('ISL-0021', 'Hadith and Sunnah', 'Books of hadith', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Hadith literature', 'The six major books of hadith are together called:', '["Muwatta", "Musnad", "Sunan Kubra", "Sihah Sittah"]', 3, 'Sihah Sittah: Bukhari, Muslim, Abu Dawud, Tirmidhi, Nasai and Ibn Majah.', '{"0": "The Muwatta is Imam Malik''s book.", "1": "A Musnad is a collection arranged by narrator, such as Musnad Ahmad.", "2": "This is the title of individual books, such as al-Bayhaqi''s."}'),
  ('ISL-0022', 'Hadith and Sunnah', 'Books of hadith', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Hadith literature', 'Al-Muwatta, one of the earliest books of hadith and law, was compiled by:', '["Imam Ahmad bin Hanbal", "Imam Tirmidhi", "Imam Malik bin Anas", "Imam Abu Hanifa"]', 2, 'Imam Malik of Madinah (died 179 AH) compiled al-Muwatta.', '{"0": "Imam Ahmad compiled the Musnad.", "1": "Imam Tirmidhi compiled the Jami.", "3": "Abu Hanifa''s teachings were recorded by his students."}'),
  ('ISL-0023', 'Hadith and Sunnah', 'Narrators', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Narrators of hadith', 'Which companion narrated the largest number of hadith?', '["Hazrat Abdullah bin Umar (RA)", "Hazrat Aisha (RA)", "Hazrat Abu Hurairah (RA)", "Hazrat Anas bin Malik (RA)"]', 2, 'About 5,374 narrations are reported from Abu Hurairah (RA), the most of any companion.', '{"0": "Ibn Umar (RA) narrated many, but fewer than Abu Hurairah (RA).", "1": "Aisha (RA) narrated over two thousand, fewer than Abu Hurairah (RA).", "3": "Anas (RA) narrated many, but fewer than Abu Hurairah (RA)."}'),
  ('ISL-0024', 'Hadith and Sunnah', 'Terms', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Hadith terms', 'In hadith studies, the chain of narrators is called the:', '["Tafsir", "Matn", "Riwayah", "Isnad (sanad)"]', 3, 'Each hadith has an isnad (the chain of people who passed it on) and a matn (its words).', '{"0": "Tafsir means explanation of the Quran.", "1": "The matn is the text of the hadith itself.", "2": "Riwayah means narration in general."}'),
  ('ISL-0025', 'Hadith and Sunnah', 'Terms', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Hadith terms', 'A hadith in which the Holy Prophet (PBUH) reports words from Allah, outside the Quran, is called a:', '["Hadith Mursal", "Hadith Qudsi", "Hadith Mutawatir", "Hadith Da''if"]', 1, 'In a Hadith Qudsi the meaning is from Allah and the wording is the Holy Prophet''s (PBUH).', '{"0": "Mursal means a link after the Successor is missing.", "2": "Mutawatir means narrated by so many people that error is ruled out.", "3": "Da''if means weak."}'),
  ('ISL-0026', 'Hadith and Sunnah', 'Famous hadith', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Sahih al-Bukhari, hadith 1', 'The first hadith in Sahih al-Bukhari teaches that:', '["Seeking knowledge is a duty on every Muslim", "Religion is sincere advice", "Cleanliness is half of faith", "Actions are judged by intentions"]', 3, 'Bukhari opens with ''Actions are but by intentions'', narrated by Umar (RA).', '{"0": "That hadith is in Sunan Ibn Majah.", "1": "That hadith is in Sahih Muslim.", "2": "That hadith is in Sahih Muslim, in the book of purification."}'),
  ('ISL-0027', 'Life of the Holy Prophet', 'Early life', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Sirah: birth', 'The Holy Prophet (PBUH) was born in the ''Year of the Elephant'', which is about:', '["610 AD", "632 AD", "570 AD", "622 AD"]', 2, 'He was born in Makkah in the year Abraha''s army with elephants attacked the Kaaba, about 570 AD.', '{"0": "610 AD is about when the first revelation came.", "1": "632 AD is the year he passed away.", "3": "622 AD is the year of the Hijrah."}'),
  ('ISL-0028', 'Life of the Holy Prophet', 'Early life', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Sirah: childhood', 'The Holy Prophet''s (PBUH) wet nurse, of the tribe of Banu Saad, was:', '["Hazrat Halimah Sadiah", "Hazrat Fatimah bint Asad", "Hazrat Umm Ayman", "Hazrat Aminah"]', 0, 'Following Arab custom, he spent his early years with Halimah Sadiah in the desert.', '{"1": "Fatimah bint Asad was Abu Talib''s wife and Ali''s (RA) mother.", "2": "Umm Ayman (Barakah) cared for him in Makkah.", "3": "Aminah was his mother."}'),
  ('ISL-0029', 'Life of the Holy Prophet', 'Early life', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Sirah: childhood', 'After his grandfather Abdul Muttalib died, the Holy Prophet (PBUH) was raised by his uncle:', '["Abbas", "Abu Talib", "Hamza", "Abu Lahab"]', 1, 'His father died before his birth and his mother when he was six; his grandfather cared for him until he was eight, then Abu Talib.', '{"0": "Abbas (RA) was an uncle who embraced Islam later.", "2": "Hamza (RA) was another uncle, who embraced Islam and was martyred at Uhud.", "3": "Abu Lahab was an uncle who opposed Islam."}'),
  ('ISL-0030', 'Life of the Holy Prophet', 'Early life', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Sirah: character', 'Before prophethood, the people of Makkah called the Holy Prophet (PBUH):', '["Saifullah", "Asadullah", "Al-Amin (the trustworthy)", "Al-Farooq"]', 2, 'He was known as Al-Amin and As-Sadiq for his honesty.', '{"0": "Saifullah (the Sword of Allah) is Khalid bin Walid''s (RA) title.", "1": "Asadullah (the Lion of Allah) is Ali''s (RA) and Hamza''s (RA) title.", "3": "Al-Farooq is Umar''s (RA) title."}'),
  ('ISL-0031', 'Life of the Holy Prophet', 'Early life', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Sirah: rebuilding of the Kaaba', 'When the Kaaba was rebuilt, the Holy Prophet (PBUH) settled the tribes'' dispute over who would place the:', '["Hajar-e-Aswad (Black Stone)", "Door of the Kaaba", "Kiswah (cover)", "Maqam-e-Ibrahim"]', 0, 'At about 35, he had the stone put on a cloth so every clan''s chief could lift it, then set it in place himself.', '{"1": "The door was not the cause of the dispute.", "2": "The covering was not the cause of the dispute.", "3": "Maqam-e-Ibrahim is the stone Prophet Ibrahim (AS) stood on, not the subject of the dispute."}'),
  ('ISL-0032', 'Life of the Holy Prophet', 'Family', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Sirah: family', 'The first wife of the Holy Prophet (PBUH) was:', '["Hazrat Aisha (RA)", "Hazrat Khadijah (RA)", "Hazrat Hafsah (RA)", "Hazrat Sawdah (RA)"]', 1, 'He married Khadijah (RA) at the age of 25; she was the first person to believe in his message.', '{"0": "Aisha (RA) married him in Madinah.", "2": "Hafsah (RA), daughter of Umar (RA), married him in Madinah.", "3": "Sawdah (RA) married him after Khadijah (RA) died."}'),
  ('ISL-0033', 'Life of the Holy Prophet', 'Prophethood', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Sirah: first revelation', 'At what age did the Holy Prophet (PBUH) receive the first revelation?', '["25", "40", "53", "35"]', 1, 'The first revelation came in Cave Hira when he was 40.', '{"0": "He married Hazrat Khadijah (RA) at 25.", "2": "At 53 he migrated to Madinah.", "3": "At 35 he settled the Black Stone dispute."}'),
  ('ISL-0034', 'Life of the Holy Prophet', 'Makkan period', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Sirah: boycott', 'The Banu Hashim were boycotted and confined in Shi''b Abi Talib for about:', '["Ten years", "One year", "Three years", "Five years"]', 2, 'The Quraysh boycotted the Banu Hashim from the 7th to the 10th year of prophethood.', '{"0": "Ten years is about the length of the Madinan period.", "1": "The boycott lasted much longer.", "3": "It ended after about three years."}'),
  ('ISL-0035', 'Life of the Holy Prophet', 'Makkan period', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Sirah: Year of Sorrow', 'The ''Year of Sorrow'' (Aam-ul-Huzn) is so called because in it the Holy Prophet (PBUH) lost:', '["his parents", "Hazrat Khadijah (RA) and Abu Talib", "his son Ibrahim", "Hazrat Hamza (RA) and Hazrat Musab (RA)"]', 1, 'Both died in the 10th year of prophethood, soon after the boycott ended.', '{"0": "His parents had died in his childhood.", "2": "His son Ibrahim died in Madinah in 10 AH.", "3": "They were martyred at Uhud in 3 AH."}'),
  ('ISL-0036', 'Life of the Holy Prophet', 'Makkan period', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Sirah: migration to Abyssinia', 'The first migration of Muslims, to escape persecution in Makkah, was to:', '["Taif", "Madinah", "Abyssinia (Habshah)", "Syria"]', 2, 'In the 5th year of prophethood a group migrated to Abyssinia, whose Christian king, the Najashi, protected them.', '{"0": "The Holy Prophet (PBUH) visited Taif but no Muslims settled there.", "1": "The migration to Madinah came years later, in 622 AD.", "3": "Syria was not a place of refuge for the early Muslims."}'),
  ('ISL-0037', 'Life of the Holy Prophet', 'Mi''raj', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Sahih al-Bukhari, Book of Prayer, hadith 349', 'Five daily prayers were made obligatory on the occasion of:', '["the Battle of Badr", "Mi''raj", "the Farewell Hajj", "the Hijrah"]', 1, 'On the night of Isra and Mi''raj, before the Hijrah, Allah made five daily prayers obligatory.', '{"0": "Badr was a battle in 2 AH.", "2": "The Farewell Hajj was in 10 AH.", "3": "The prayers were already obligatory before the Hijrah."}'),
  ('ISL-0038', 'Life of the Holy Prophet', 'Hijrah', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran 9:40', 'During the Hijrah, the Holy Prophet (PBUH) and Hazrat Abu Bakr (RA) hid for three days in the Cave of:', '["Hira", "Uhud", "Arafat", "Thawr"]', 3, 'They hid in Cave Thawr, south of Makkah, before going on to Madinah. The Quran refers to it in At-Tawbah 9:40.', '{"0": "Cave Hira is where the first revelation came.", "1": "Uhud is a mountain near Madinah.", "2": "Arafat is a plain near Makkah, used in Hajj."}'),
  ('ISL-0039', 'Life of the Holy Prophet', 'Hijrah', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Sirah: Hijrah', 'The first mosque built by the Holy Prophet (PBUH) was:', '["Masjid al-Qiblatain", "Masjid al-Aqsa", "Masjid-e-Nabawi", "Masjid Quba"]', 3, 'He built Masjid Quba on arrival at the edge of Madinah in 622 AD.', '{"0": "Masjid al-Qiblatain is where the qiblah was changed, in 2 AH.", "1": "Masjid al-Aqsa is in Jerusalem and was not built by him.", "2": "Masjid-e-Nabawi was built in Madinah after Quba."}'),
  ('ISL-0040', 'Life of the Holy Prophet', 'Madinan period', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Sirah: Mawakhat', 'The bond of brotherhood (Mawakhat) set up by the Holy Prophet (PBUH) in Madinah was between:', '["the Quraysh and the Ansar", "the Aws and the Khazraj", "the Ansar and the Muhajirun", "the Muslims and the Jews of Madinah"]', 2, 'Each emigrant from Makkah (Muhajir) was paired with a helper of Madinah (Ansari) as a brother.', '{"0": "The Quraysh as a tribe were still opposed to Islam.", "1": "The Aws and Khazraj were both Ansar tribes; Islam ended their feud, but Mawakhat paired Ansar with Muhajirun.", "3": "Their relations were set by the Charter of Madinah, not Mawakhat."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Islamiat', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('ISL-0041', 'Life of the Holy Prophet', 'Madinan period', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran 2:144; Sahih al-Bukhari, hadith 40', 'The qiblah was changed from Bait-ul-Maqdis to the Kaaba in:', '["2 AH", "1 AH", "5 AH", "8 AH"]', 0, 'Al-Baqarah 2:144 ordered Muslims to face the Masjid al-Haram, about 16-17 months after the Hijrah.', '{"1": "For about 16-17 months after the Hijrah, Muslims faced Bait-ul-Maqdis.", "2": "5 AH is the year of the Battle of the Trench.", "3": "8 AH is the year of the Conquest of Makkah."}'),
  ('ISL-0042', 'Life of the Holy Prophet', 'Battles', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Sirah: Battle of Badr', 'The Battle of Badr was fought in:', '["3 AH", "2 AH", "5 AH", "8 AH"]', 1, 'About 313 Muslims defeated a Quraysh army of about 1,000 at Badr in Ramadan 2 AH.', '{"0": "3 AH is the Battle of Uhud.", "2": "5 AH is the Battle of the Trench.", "3": "8 AH is the Conquest of Makkah and the Battle of Hunain."}'),
  ('ISL-0043', 'Life of the Holy Prophet', 'Battles', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Sirah: Battle of Uhud', 'Hazrat Hamza (RA), called Sayyid-ush-Shuhada, was martyred in the Battle of:', '["Hunain", "Khandaq", "Uhud", "Badr"]', 2, 'Hamza (RA), the Holy Prophet''s (PBUH) uncle, was martyred at Uhud in 3 AH.', '{"0": "Hunain was in 8 AH, after Hamza''s (RA) martyrdom.", "1": "Hamza (RA) had already been martyred by then.", "3": "Hamza (RA) fought bravely at Badr and survived."}'),
  ('ISL-0044', 'Life of the Holy Prophet', 'Battles', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Sirah: Battle of the Ditch', 'The trench dug around Madinah in the Battle of the Ditch (Khandaq) was suggested by:', '["Hazrat Ali (RA)", "Hazrat Salman Farsi (RA)", "Hazrat Umar (RA)", "Hazrat Khalid bin Walid (RA)"]', 1, 'Salman Farsi (RA) suggested the Persian method of defending a city with a trench, in 5 AH.', '{"0": "Ali (RA) fought Amr bin Abd Wudd there, but the idea was Salman''s (RA).", "2": "Umar (RA) took part but did not suggest the trench.", "3": "Khalid (RA) had not yet embraced Islam."}'),
  ('ISL-0045', 'Life of the Holy Prophet', 'Hudaybiyyah', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Sirah: Treaty of Hudaybiyyah', 'Before the Treaty of Hudaybiyyah, the Holy Prophet (PBUH) sent which companion to the Quraysh as his envoy?', '["Hazrat Ali (RA)", "Hazrat Bilal (RA)", "Hazrat Umar (RA)", "Hazrat Uthman (RA)"]', 3, 'A rumour that Uthman (RA) had been killed led to the pledge of Bait-e-Rizwan under the tree.', '{"0": "Ali (RA) wrote down the treaty, but was not the envoy.", "1": "Bilal (RA) was not sent as envoy.", "2": "Umar (RA) suggested Uthman (RA), who had more kin in Makkah."}'),
  ('ISL-0046', 'Life of the Holy Prophet', 'Hudaybiyyah', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Sirah: Treaty of Hudaybiyyah', 'The Treaty of Hudaybiyyah (6 AH) was a truce between Muslims and the Quraysh for:', '["5 years", "10 years", "20 years", "2 years"]', 1, 'The treaty fixed ten years of peace; the Quraysh''s breach led to the Conquest of Makkah in 8 AH.', '{"0": "The agreed term was ten years.", "2": "The agreed term was ten years.", "3": "The truce was agreed for much longer, though the Quraysh broke it within two years."}'),
  ('ISL-0047', 'Life of the Holy Prophet', 'Conquest of Makkah', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Sirah: Conquest of Makkah', 'Makkah was conquered by the Muslims in:', '["6 AH", "8 AH", "10 AH", "7 AH"]', 1, 'Makkah was taken almost without fighting in Ramadan 8 AH, and a general amnesty was given.', '{"0": "6 AH is the Treaty of Hudaybiyyah.", "2": "10 AH is the Farewell Hajj.", "3": "7 AH is the conquest of Khaybar."}'),
  ('ISL-0048', 'Life of the Holy Prophet', 'Farewell Hajj', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Sirah: Farewell Hajj', 'The Holy Prophet (PBUH) performed his only Hajj, the Farewell Hajj, in:', '["9 AH", "11 AH", "8 AH", "10 AH"]', 3, 'He gave the Farewell Sermon at Arafat during this Hajj, in 10 AH (632 AD).', '{"0": "In 9 AH Hazrat Abu Bakr (RA) led the Hajj.", "1": "The Holy Prophet (PBUH) passed away in 11 AH.", "2": "8 AH is the Conquest of Makkah."}'),
  ('ISL-0049', 'Life of the Holy Prophet', 'Passing away', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Sirah: passing away', 'The Holy Prophet (PBUH) passed away in 11 AH at the age of:', '["60", "53", "63", "65"]', 2, 'He passed away in Madinah in Rabi-ul-Awwal 11 AH (632 AD), aged 63, and is buried in Masjid-e-Nabawi.', '{"0": "He lived to 63.", "1": "53 was his age at the Hijrah.", "3": "He lived to 63."}'),
  ('ISL-0050', 'Beliefs and worship', 'Pillars of Islam', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Sahih al-Bukhari, hadith 8', 'Which of these is NOT one of the five pillars of Islam?', '["Hajj", "Jihad", "Sawm (fasting)", "Zakat"]', 1, 'The pillars are Shahadah, Salah, Zakat, Sawm and Hajj (Sahih al-Bukhari, hadith 8). Jihad is a duty, but not one of the five pillars.', '{"0": "Hajj is the fifth pillar.", "2": "Fasting in Ramadan is the fourth pillar.", "3": "Zakat is the third pillar."}'),
  ('ISL-0051', 'Beliefs and worship', 'Zakat', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Zakat', 'The literal meaning of ''Zakat'' is:', '["To purify and grow", "To fast", "To pray", "To give in secret"]', 0, 'Zakat means purification and growth: it cleanses wealth and makes it grow.', '{"1": "Fasting is sawm.", "2": "Prayer is salah.", "3": "Giving in secret is praised, but it is not the meaning of zakat."}'),
  ('ISL-0052', 'Beliefs and worship', 'Zakat', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Zakat', 'The rate of zakat on savings of cash, gold and silver is:', '["5 per cent", "10 per cent", "20 per cent", "2.5 per cent"]', 3, 'Zakat of one-fortieth (2.5%) is due on savings above the nisab held for a lunar year.', '{"0": "5 per cent is the ushr rate on land watered by irrigation.", "1": "10 per cent is the ushr rate on rain-watered land.", "2": "20 per cent (khums) applies to buried treasure."}'),
  ('ISL-0053', 'Beliefs and worship', 'Hajj', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Jami at-Tirmidhi, Book of Hajj, hadith 889', 'The essential act of Hajj (Rukn-e-Azam) without which Hajj is not valid is:', '["Wuquf at Arafat", "Tawaf of the Kaaba", "Stoning the Jamarat", "Sa''i between Safa and Marwah"]', 0, '''Hajj is Arafah'' (Jami at-Tirmidhi): standing at Arafat on 9 Dhul Hijjah is the heart of Hajj.', '{"1": "Tawaf is required, but missing Arafat cannot be made up.", "2": "Stoning is wajib; a missed stoning is made up with a sacrifice.", "3": "Sa''i is required, but Arafat is the central rite."}'),
  ('ISL-0054', 'Beliefs and worship', 'Hajj', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran 2:158', 'Sa''i is walking seven times between the hills of:', '["Arafat and Muzdalifah", "Uhud and Thawr", "Safa and Marwah", "Mina and Arafat"]', 2, 'Sa''i recalls Hazrat Hajra''s search for water for Ismail (AS) (Al-Baqarah 2:158).', '{"0": "Pilgrims travel between these, but that is not Sa''i.", "1": "These are in Madinah and Makkah, unconnected to Sa''i.", "3": "Pilgrims travel between these, but that is not Sa''i."}'),
  ('ISL-0055', 'Beliefs and worship', 'Hajj', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Hajj', 'How many times do pilgrims go around the Kaaba in one tawaf?', '["Five", "Three", "Seven", "Nine"]', 2, 'Every tawaf is seven rounds, starting and ending at the Black Stone.', '{"0": "Five is the number of daily prayers.", "1": "Three is the number of rounds done briskly (ramal) in some tawafs, not the total.", "3": "A tawaf has seven rounds."}'),
  ('ISL-0056', 'Beliefs and worship', 'Adhan', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Sunan Abu Dawud, Book of Prayer, hadith 499', 'The first muezzin of Islam was:', '["Hazrat Bilal (RA)", "Hazrat Abdullah bin Umm Maktum (RA)", "Hazrat Ammar bin Yasir (RA)", "Hazrat Abdullah bin Zaid (RA)"]', 0, 'Bilal (RA) was chosen for his strong voice when the adhan began in Madinah in 1 AH.', '{"1": "Ibn Umm Maktum (RA) also called the adhan, but after Bilal (RA).", "2": "Ammar (RA) was an early Muslim but not the muezzin.", "3": "Abdullah bin Zaid (RA) saw the adhan in a dream, but Bilal (RA) called it."}'),
  ('ISL-0057', 'Beliefs and worship', 'Angels', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Belief in angels', 'The angel who will blow the trumpet on the Day of Judgement is:', '["Hazrat Jibrail (AS)", "Hazrat Izrail (AS)", "Hazrat Mikail (AS)", "Hazrat Israfil (AS)"]', 3, 'Israfil (AS) is the angel of the trumpet (sur).', '{"0": "Jibrail (AS) brought revelation.", "1": "Izrail (AS) takes souls at death.", "2": "Mikail (AS) is linked with rain and provision."}'),
  ('ISL-0058', 'Beliefs and worship', 'Revealed books', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran 4:163', 'The Zabur was revealed to:', '["Hazrat Ibrahim (AS)", "Hazrat Musa (AS)", "Hazrat Dawud (AS)", "Hazrat Isa (AS)"]', 2, 'An-Nisa 4:163: ''and to Dawud We gave the Zabur.''', '{"0": "Scrolls (suhuf) were revealed to Ibrahim (AS).", "1": "The Tawrat was revealed to Musa (AS).", "3": "The Injil was revealed to Isa (AS)."}'),
  ('ISL-0059', 'Beliefs and worship', 'Revealed books', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran 5:44', 'The Tawrat was revealed to:', '["Hazrat Nuh (AS)", "Hazrat Dawud (AS)", "Hazrat Isa (AS)", "Hazrat Musa (AS)"]', 3, 'The Tawrat (Torah) was given to Musa (AS) (Al-Maidah 5:44).', '{"0": "No named book was revealed to Nuh (AS).", "1": "The Zabur was revealed to Dawud (AS).", "2": "The Injil was revealed to Isa (AS)."}'),
  ('ISL-0060', 'Beliefs and worship', 'Fasting', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran 2:183-185', 'Fasting in Ramadan was made obligatory in:', '["8 AH", "Before the Hijrah", "1 AH", "2 AH"]', 3, 'Al-Baqarah 2:183-185 made the fast of Ramadan obligatory in 2 AH, the year of Badr.', '{"0": "8 AH is the Conquest of Makkah.", "1": "It was made obligatory in Madinah.", "2": "Fasting in Ramadan was not yet obligatory in the first year after the Hijrah."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Islamiat', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('ISL-0061', 'Beliefs and worship', 'Beliefs', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran 4:48', 'Associating partners with Allah is called:', '["Kufr", "Shirk", "Nifaq", "Bid''ah"]', 1, 'Shirk is the sin that Allah does not forgive if one dies upon it (An-Nisa 4:48).', '{"0": "Kufr is disbelief in general.", "2": "Nifaq is hypocrisy.", "3": "Bid''ah is innovation in religion."}'),
  ('ISL-0062', 'Beliefs and worship', 'Beliefs', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran 33:40; Constitution of Pakistan, Article 260(3)', 'The belief that the Holy Prophet Muhammad (PBUH) is the last prophet is called:', '["Tauheed", "Khatm-e-Nabuwwat", "Taqdir", "Akhirah"]', 1, 'Al-Ahzab 33:40 calls him ''the Messenger of Allah and the Seal of the Prophets''.', '{"0": "Tauheed is belief in the Oneness of Allah.", "2": "Taqdir is belief in divine decree.", "3": "Akhirah is belief in the Hereafter."}'),
  ('ISL-0063', 'Beliefs and worship', 'Prayer', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Salah', 'How many fard rak''ahs are there in the Maghrib prayer?', '["Four", "Five", "Two", "Three"]', 3, 'Maghrib is the only daily prayer with three fard rak''ahs.', '{"0": "Zuhr, Asr and Isha have four fard rak''ahs.", "1": "No prayer has five fard rak''ahs.", "2": "Fajr has two fard rak''ahs."}'),
  ('ISL-0064', 'Beliefs and worship', 'Purification', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran 5:6', 'Purifying oneself with clean earth when water is not available is called:', '["Wudu", "Istinja", "Tayammum", "Ghusl"]', 2, 'Tayammum is allowed when water cannot be found or used (An-Nisa 4:43, Al-Maidah 5:6).', '{"0": "Wudu is ablution with water.", "1": "Istinja is cleaning after using the toilet.", "3": "Ghusl is the full bath."}'),
  ('ISL-0065', 'The Rightly Guided Caliphs', 'Hazrat Abu Bakr (RA)', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), The Rightly Guided Caliphs', 'Hazrat Abu Bakr (RA) is known by the title:', '["Al-Farooq", "Ghani", "As-Siddiq", "Haidar-e-Karrar"]', 2, 'He was called As-Siddiq for at once confirming the Holy Prophet''s (PBUH) account of the Mi''raj.', '{"0": "Al-Farooq is Umar''s (RA) title.", "1": "Ghani is Uthman''s (RA) title.", "3": "Haidar-e-Karrar is Ali''s (RA) title."}'),
  ('ISL-0066', 'The Rightly Guided Caliphs', 'Hazrat Umar (RA)', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Caliphate of Umar (RA)', 'The Hijri calendar was introduced during the caliphate of:', '["Hazrat Ali (RA)", "Hazrat Abu Bakr (RA)", "Hazrat Uthman (RA)", "Hazrat Umar (RA)"]', 3, 'Umar (RA) adopted a calendar counting from the Hijrah, around 17 AH (638 AD).', '{"0": "Ali (RA) proposed the Hijrah as the starting point, but the calendar was adopted by Umar (RA).", "1": "Abu Bakr''s (RA) short caliphate did not introduce it.", "2": "It was already in use under Uthman (RA)."}'),
  ('ISL-0067', 'The Rightly Guided Caliphs', 'Hazrat Umar (RA)', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Caliphate of Umar (RA)', 'Jerusalem (Bait-ul-Maqdis) came under Muslim rule during the caliphate of:', '["Hazrat Ali (RA)", "Hazrat Umar (RA)", "Hazrat Uthman (RA)", "Hazrat Abu Bakr (RA)"]', 1, 'Umar (RA) travelled to Jerusalem in 637-638 AD to receive its surrender and gave its people a pledge of safety.', '{"0": "Jerusalem was already Muslim before Ali (RA).", "2": "Jerusalem was already Muslim before Uthman (RA).", "3": "Syria was being fought for when Abu Bakr (RA) died."}'),
  ('ISL-0068', 'The Rightly Guided Caliphs', 'Hazrat Uthman (RA)', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), The Rightly Guided Caliphs', 'Hazrat Uthman (RA) is called ''Zun-Nurain'' (possessor of two lights) because:', '["he compiled the Quran twice", "he bought two wells for Muslims", "he married two daughters of the Holy Prophet (PBUH)", "he migrated twice"]', 2, 'He married Ruqayyah (RA) and, after her death, Umm Kulthum (RA).', '{"0": "He issued standard copies once.", "1": "He bought the well of Rumah; that is not the reason for the title.", "3": "He did migrate to Abyssinia and Madinah, but the title refers to his marriages."}'),
  ('ISL-0069', 'The Rightly Guided Caliphs', 'Hazrat Ali (RA)', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Caliphate of Ali (RA)', 'Hazrat Ali (RA) moved the capital of the caliphate from Madinah to:', '["Baghdad", "Damascus", "Kufa", "Basra"]', 2, 'Ali (RA) made Kufa, in Iraq, his capital in 36 AH.', '{"0": "Baghdad was founded by the Abbasids in 762 AD.", "1": "Damascus became the capital under the Umayyads.", "3": "Basra was a garrison city, not Ali''s (RA) capital."}'),
  ('ISL-0070', 'The Rightly Guided Caliphs', 'Order of caliphs', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), The Rightly Guided Caliphs', 'Who was the third Rightly Guided Caliph?', '["Hazrat Uthman (RA)", "Hazrat Abu Bakr (RA)", "Hazrat Umar (RA)", "Hazrat Ali (RA)"]', 0, 'The order is Abu Bakr, Umar, Uthman and Ali (may Allah be pleased with them).', '{"1": "Abu Bakr (RA) was the first caliph.", "2": "Umar (RA) was the second caliph.", "3": "Ali (RA) was the fourth caliph."}'),
  ('ISL-0071', 'The Rightly Guided Caliphs', 'Hazrat Abu Bakr (RA)', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Caliphate of Abu Bakr (RA)', 'The wars against false prophets and those who refused zakat after the Holy Prophet''s (PBUH) death were fought under:', '["Hazrat Abu Bakr (RA)", "Hazrat Ali (RA)", "Hazrat Uthman (RA)", "Hazrat Umar (RA)"]', 0, 'Abu Bakr (RA) fought the Riddah wars, including the battle of Yamamah against Musaylimah.', '{"1": "They were over long before Ali (RA).", "2": "They were over long before Uthman (RA).", "3": "They were over before Umar (RA) became caliph."}'),
  ('ISL-0072', 'Prophets and companions', 'Prophets', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran 4:125', 'Which prophet is called Khalilullah (the friend of Allah)?', '["Hazrat Ibrahim (AS)", "Hazrat Adam (AS)", "Hazrat Isa (AS)", "Hazrat Musa (AS)"]', 0, 'An-Nisa 4:125: ''Allah took Ibrahim as a friend (khalil).''', '{"1": "Adam (AS) is called Safiullah.", "2": "Isa (AS) is called Ruhullah.", "3": "Musa (AS) is called Kalimullah, as Allah spoke to him."}'),
  ('ISL-0073', 'Prophets and companions', 'Prophets', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran 4:164', 'Which prophet is called Kalimullah because Allah spoke to him directly?', '["Hazrat Yunus (AS)", "Hazrat Nuh (AS)", "Hazrat Ibrahim (AS)", "Hazrat Musa (AS)"]', 3, 'An-Nisa 4:164: ''and Allah spoke to Musa directly.''', '{"0": "Yunus (AS) is known for the fish.", "1": "Nuh (AS) is known for the Ark.", "2": "Ibrahim (AS) is Khalilullah."}'),
  ('ISL-0074', 'Prophets and companions', 'Prophets', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran 37:139-144', 'Which prophet was swallowed by a great fish?', '["Hazrat Yusuf (AS)", "Hazrat Ilyas (AS)", "Hazrat Ayyub (AS)", "Hazrat Yunus (AS)"]', 3, 'As-Saffat 37:139-144 tells of Yunus (AS) and the fish; he is called Dhun-Nun.', '{"0": "Yusuf (AS) was thrown into a well by his brothers.", "1": "Ilyas (AS) called his people away from the idol Baal.", "2": "Ayyub (AS) is known for patience in illness."}'),
  ('ISL-0075', 'Prophets and companions', 'Prophets', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran 11:37', 'Which prophet built the Ark?', '["Hazrat Sulaiman (AS)", "Hazrat Nuh (AS)", "Hazrat Hud (AS)", "Hazrat Ibrahim (AS)"]', 1, 'Hud 11:37: ''And build the ship under Our eyes and Our inspiration.''', '{"0": "Sulaiman (AS) built the Temple in Jerusalem.", "2": "Hud (AS) was sent to the people of Ad.", "3": "Ibrahim (AS) built the Kaaba with Ismail (AS)."}'),
  ('ISL-0076', 'Prophets and companions', 'Prophets', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran 2:127', 'Prophet Ibrahim (AS) raised the walls of the Kaaba together with:', '["Hazrat Ismail (AS)", "Hazrat Yaqub (AS)", "Hazrat Lut (AS)", "Hazrat Ishaq (AS)"]', 0, 'Al-Baqarah 2:127: ''when Ibrahim was raising the foundations of the House, and Ismail.''', '{"1": "Yaqub (AS) was Ibrahim''s (AS) grandson.", "2": "Lut (AS) was Ibrahim''s (AS) nephew, sent to Sodom.", "3": "Ishaq (AS) lived in Palestine."}'),
  ('ISL-0077', 'Prophets and companions', 'Prophets', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Concordance of the Holy Quran (al-Mu''jam al-Mufahras)', 'The prophet mentioned by name most often in the Holy Quran is:', '["Hazrat Nuh (AS)", "Hazrat Isa (AS)", "Hazrat Ibrahim (AS)", "Hazrat Musa (AS)"]', 3, 'Musa (AS) is named about 136 times, more than any other prophet.', '{"0": "Nuh (AS) is named about 43 times.", "1": "Isa (AS) is named about 25 times.", "2": "Ibrahim (AS) is named about 69 times, fewer than Musa (AS)."}'),
  ('ISL-0078', 'Prophets and companions', 'Companions', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Sahih al-Bukhari, hadith 4262', 'Which companion is known as ''Saifullah'' (the Sword of Allah)?', '["Hazrat Abu Ubaidah (RA)", "Hazrat Hamza (RA)", "Hazrat Khalid bin Walid (RA)", "Hazrat Saad bin Abi Waqqas (RA)"]', 2, 'The Holy Prophet (PBUH) gave Khalid (RA) this title after the Battle of Mu''tah.', '{"0": "Abu Ubaidah (RA) is called Amin-ul-Ummat.", "1": "Hamza (RA) is called Asadullah and Sayyid-ush-Shuhada.", "3": "Saad (RA) led the conquest of Persia at Qadisiyyah."}'),
  ('ISL-0079', 'Prophets and companions', 'Companions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Sahih al-Bukhari, hadith 3744', 'Which companion is called ''Amin-ul-Ummat'' (the trustee of this Ummah)?', '["Hazrat Talhah (RA)", "Hazrat Abu Bakr (RA)", "Hazrat Abu Ubaidah bin al-Jarrah (RA)", "Hazrat Zubair (RA)"]', 2, 'The Holy Prophet (PBUH) said: ''Every nation has a trustee, and the trustee of this nation is Abu Ubaidah.''', '{"0": "Talhah (RA) is called Talhat-ul-Khair.", "1": "Abu Bakr (RA) is As-Siddiq.", "3": "Zubair (RA) is called the disciple (hawari) of the Holy Prophet (PBUH)."}'),
  ('ISL-0080', 'Prophets and companions', 'Companions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Early Muslims', 'Hazrat Sumayyah (RA) is remembered as:', '["the first woman to memorise the Quran", "the wet nurse of the Holy Prophet (PBUH)", "the first woman to accept Islam", "the first martyr of Islam"]', 3, 'Sumayyah (RA), mother of Ammar bin Yasir (RA), was killed by Abu Jahl for refusing to give up Islam.', '{"0": "She was martyred early in Makkah; this is not what she is known for.", "1": "Halimah Sadiah was his wet nurse.", "2": "Khadijah (RA) was the first woman to accept Islam."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Islamiat', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('ISL-0081', 'Prophets and companions', 'Companions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Jami at-Tirmidhi, hadith 3747', 'The ten companions given glad tidings of Paradise in one hadith are called:', '["Ashab al-Suffah", "Ansar", "Ashara Mubashara", "Ahl al-Bayt"]', 2, 'Abdur Rahman bin Awf (RA) narrated the hadith naming the ten (Jami at-Tirmidhi, hadith 3747).', '{"0": "Ashab al-Suffah lived on the platform of Masjid-e-Nabawi to learn.", "1": "The Ansar were the Muslims of Madinah.", "3": "Ahl al-Bayt means the Holy Prophet''s (PBUH) household."}'),
  ('ISL-0082', 'Prophets and companions', 'Companions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Pledges of Aqabah', 'Who was sent by the Holy Prophet (PBUH) as the first teacher of Islam to Madinah, before the Hijrah?', '["Hazrat Zaid bin Thabit (RA)", "Hazrat Abu Bakr (RA)", "Hazrat Bilal (RA)", "Hazrat Musab bin Umair (RA)"]', 3, 'After the first Pledge of Aqabah, Musab (RA) went to Madinah to teach the Quran; he was martyred at Uhud.', '{"0": "Zaid (RA) was a young man of Madinah, later a scribe.", "1": "Abu Bakr (RA) migrated with the Holy Prophet (PBUH).", "2": "Bilal (RA) migrated with the other Makkan Muslims."}'),
  ('ISL-0083', 'Islamic law and society', 'Sources of law', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Sources of Islamic law', 'The four sources of Islamic law, in order, are:', '["Sunnah, Quran, Qiyas, Ijma", "Quran, Sunnah, Ijma, Qiyas", "Quran, Ijma, Sunnah, Qiyas", "Quran, Qiyas, Ijma, Sunnah"]', 1, 'Jurists first look to the Quran, then the Sunnah, then consensus (ijma), then analogy (qiyas).', '{"0": "The Quran is always the first source.", "2": "The Sunnah comes straight after the Quran.", "3": "Qiyas, reasoning by analogy, comes last."}'),
  ('ISL-0084', 'Islamic law and society', 'Schools of law', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), The four imams', 'Imam Ahmad bin Hanbal was a student of:', '["Imam Abu Hanifa", "Imam Bukhari", "Imam Malik", "Imam Shafi''i"]', 3, 'Imam Ahmad studied with Imam Shafi''i in Baghdad; Shafi''i had studied with Imam Malik.', '{"0": "Abu Hanifa died in 150 AH, before Imam Ahmad was born (164 AH).", "1": "Imam Bukhari was Imam Ahmad''s own student.", "2": "Imam Malik died in 179 AH, before Imam Ahmad studied fiqh."}'),
  ('ISL-0085', 'Islamic law and society', 'Schools of law', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), The four imams', 'Most Sunni Muslims in Pakistan follow the school of:', '["Imam Malik", "Imam Shafi''i", "Imam Ahmad bin Hanbal", "Imam Abu Hanifa"]', 3, 'The Hanafi school, founded on Abu Hanifa''s teachings in Kufa, is followed by most Sunnis in South Asia.', '{"0": "The Maliki school is common in North and West Africa.", "1": "The Shafi''i school is common in Egypt, East Africa and South-East Asia.", "2": "The Hanbali school is common in Saudi Arabia."}'),
  ('ISL-0086', 'Islamic law and society', 'Terms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Sunan Abu Dawud, hadith 3592', 'Using independent reasoning to find a legal ruling where the texts are silent is called:', '["Fatwa", "Taqlid", "Ijma", "Ijtihad"]', 3, 'Ijtihad is approved in the hadith of Muadh bin Jabal (RA) on judging in Yemen.', '{"0": "A fatwa is a legal opinion, which may result from ijtihad.", "1": "Taqlid is following a school''s established ruling.", "2": "Ijma is consensus of scholars."}'),
  ('ISL-0087', 'Islamic law and society', 'Family law', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran 2:229', 'Divorce sought by the wife, in return for giving up her mahr or other property, is called:', '["Talaq", "Khul''", "Zihar", "Iddah"]', 1, 'Al-Baqarah 2:229 allows a wife to free herself by giving something back; in Pakistan courts grant khul''.', '{"0": "Talaq is divorce by the husband.", "2": "Zihar is an old pre-Islamic form of separation that the Quran condemned.", "3": "Iddah is the waiting period after divorce or death."}'),
  ('ISL-0088', 'Islamic law and society', 'Inheritance', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Sahih al-Bukhari, hadith 2742', 'A Muslim may leave a bequest (wasiyyah) to non-heirs of at most:', '["One third of the estate", "The whole estate", "One quarter of the estate", "One half of the estate"]', 0, 'In the hadith of Saad bin Abi Waqqas (RA): ''One third, and one third is a lot.''', '{"1": "Heirs'' shares are fixed by the Quran, so a bequest cannot take everything.", "2": "One third, not one quarter, is the limit.", "3": "A bequest is limited to one third."}'),
  ('ISL-0089', 'Islamic law and society', 'Economy', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran 2:275', 'Islam forbids interest on loans, which in Arabic is called:', '["Zakat", "Sadaqah", "Waqf", "Riba"]', 3, 'Al-Baqarah 2:275: ''Allah has permitted trade and forbidden riba.''', '{"0": "Zakat is the obligatory alms.", "1": "Sadaqah is voluntary charity.", "2": "Waqf is a charitable endowment."}'),
  ('ISL-0090', 'Islamic law and society', 'Muslim scholars', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Muslim contributions to knowledge', 'Ibn Khaldun is known as a founder of:', '["sociology and the philosophy of history", "chemistry", "medicine", "algebra"]', 0, 'Ibn Khaldun''s Muqaddimah (1377) studied how societies rise and fall.', '{"1": "Early chemistry is credited to Jabir bin Hayyan.", "2": "Ibn Sina is the best-known Muslim physician.", "3": "Algebra is credited to al-Khwarizmi."}'),
  ('ISL-0091', 'Islamic law and society', 'Muslim scholars', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Muslim contributions to knowledge', 'Kitab al-Jabr wal-Muqabalah, from which the word ''algebra'' comes, was written by:', '["Ibn Sina", "Muhammad bin Musa al-Khwarizmi", "Jabir bin Hayyan", "Al-Biruni"]', 1, 'Al-Khwarizmi wrote it in Baghdad in the 9th century; his name gives us the word ''algorithm''.', '{"0": "Ibn Sina wrote the Qanun on medicine.", "2": "Jabir bin Hayyan wrote on chemistry.", "3": "Al-Biruni wrote Kitab al-Hind and works on astronomy."}'),
  ('ISL-0092', 'Islamic law and society', 'Muslim scholars', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), Muslim contributions to knowledge', 'Al-Qanun fi al-Tibb (The Canon of Medicine), taught in Europe for centuries, was written by:', '["Ibn Sina", "Ibn Rushd", "Al-Farabi", "Al-Razi"]', 0, 'Ibn Sina (Avicenna, died 1037) wrote the Canon, a medical encyclopaedia.', '{"1": "Ibn Rushd is best known for commentaries on Aristotle.", "2": "Al-Farabi wrote on philosophy and music.", "3": "Al-Razi wrote Al-Hawi and a treatise on smallpox and measles."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO bank_questions (bank, question_id, subject, chapter)
SELECT 'lat', id, subject, chapter FROM questions WHERE id LIKE 'ISL-%';

INSERT INTO question_counters (prefix, n) VALUES ('ISL', 92) ON CONFLICT (prefix) DO UPDATE SET n = max(n, 92);

-- LAT General Knowledge: 105 original MCQs, GK-0001 to GK-0105 (HEC LAT Part I has 20 GK MCQs).
-- Chapters: everyday science, world geography, international organisations and treaties, law and the courts, famous
-- people and books, and sports, awards and days. Current affairs is left for dated batches, since its answers change.
-- Keys were checked against the source in each question (UN Charter and agency sites, the Constitution of Pakistan,
-- textbooks, official records). Written for Markhor Prep, not copied. questions.mdcat = 0; listed in the LAT bank.

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'General Knowledge', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('GK-0001', 'Everyday science', 'Vitamins and health', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Biology 11 (PECTAA), nutrition', 'Scurvy is caused by a lack of:', '["Vitamin D", "Vitamin K", "Vitamin A", "Vitamin C"]', 3, 'Vitamin C is needed to make collagen; without it gums bleed and wounds heal slowly.', '{"0": "Lack of vitamin D causes rickets.", "1": "Lack of vitamin K slows blood clotting.", "2": "Lack of vitamin A causes night blindness."}'),
  ('GK-0002', 'Everyday science', 'Vitamins and health', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Biology 11 (PECTAA), nutrition', 'Rickets in children is caused by a lack of:', '["Iron", "Vitamin B1", "Vitamin C", "Vitamin D"]', 3, 'Vitamin D helps the body absorb calcium; without it bones stay soft and bend.', '{"0": "Lack of iron causes anaemia.", "1": "Lack of vitamin B1 causes beriberi.", "2": "Lack of vitamin C causes scurvy."}'),
  ('GK-0003', 'Everyday science', 'Vitamins and health', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Biology 12 (PECTAA), endocrine system', 'Goitre, a swelling of the thyroid gland, is usually caused by a lack of:', '["Fluoride", "Calcium", "Iron", "Iodine"]', 3, 'The thyroid needs iodine to make its hormones; iodised salt prevents goitre.', '{"0": "Lack of fluoride makes teeth decay more easily.", "1": "Lack of calcium weakens bones and teeth.", "2": "Lack of iron causes anaemia."}'),
  ('GK-0004', 'Everyday science', 'Human body', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Biology 12 (PECTAA), homeostasis', 'The largest organ of the human body is the:', '["Brain", "Skin", "Lungs", "Liver"]', 1, 'The skin of an adult covers about 1.5 to 2 square metres.', '{"0": "The brain is far smaller than the skin.", "2": "The lungs are large but smaller than the skin.", "3": "The liver is the largest internal organ."}'),
  ('GK-0005', 'Everyday science', 'Human body', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Biology 12 (PECTAA), endocrine system', 'Insulin, which controls blood sugar, is made by the:', '["Liver", "Kidneys", "Pancreas", "Thyroid gland"]', 2, 'Beta cells in the islets of Langerhans of the pancreas make insulin.', '{"0": "The liver stores glucose as glycogen, but does not make insulin.", "1": "The kidneys filter blood.", "3": "The thyroid makes thyroxine."}'),
  ('GK-0006', 'Everyday science', 'Human body', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Biology 11 (PECTAA), skeletal system', 'How many bones are in the adult human skeleton?', '["212", "206", "186", "300"]', 1, 'A newborn has about 300 bones; many fuse, leaving 206 in an adult.', '{"0": "The adult skeleton has 206 bones.", "2": "The adult skeleton has 206 bones.", "3": "About 300 is the number at birth, before some bones fuse."}'),
  ('GK-0007', 'Everyday science', 'Human body', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Biology 12 (PECTAA), homeostasis', 'Normal human body temperature is about:', '["32 °C", "98 °C", "37 °C", "40 °C"]', 2, 'Normal body temperature is about 37 °C, which is 98.6 °F.', '{"0": "32 °C would be serious hypothermia.", "1": "98 is roughly the figure in Fahrenheit (98.6 °F), not Celsius.", "3": "40 °C is a high fever."}'),
  ('GK-0008', 'Everyday science', 'Air and gases', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Chemistry 11 (PECTAA), atmosphere', 'Which gas makes up most of the Earth''s air?', '["Nitrogen", "Argon", "Carbon dioxide", "Oxygen"]', 0, 'Dry air is about 78 per cent nitrogen and 21 per cent oxygen.', '{"1": "Argon is under 1 per cent.", "2": "Carbon dioxide is only about 0.04 per cent.", "3": "Oxygen is about 21 per cent of the air."}'),
  ('GK-0009', 'Everyday science', 'Air and gases', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Chemistry 11 (PECTAA), atmosphere', 'The ozone layer protects life on Earth from the Sun''s:', '["Visible light", "Ultraviolet rays", "Radio waves", "Infrared rays"]', 1, 'Ozone in the stratosphere absorbs most harmful ultraviolet radiation.', '{"0": "Visible light reaches the ground; we see by it.", "2": "Radio waves are harmless and pass through the atmosphere.", "3": "Infrared rays are felt as heat and are not blocked by ozone."}'),
  ('GK-0010', 'Everyday science', 'Chemistry around us', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Chemistry 11 (PECTAA), states of matter', '''Dry ice'' is the solid form of:', '["Nitrogen", "Water", "Carbon dioxide", "Ammonia"]', 2, 'Solid carbon dioxide turns straight into gas at -78.5 °C, leaving no liquid; hence ''dry''.', '{"0": "Nitrogen is used as a liquid for cooling, not as dry ice.", "1": "Solid water is ordinary ice.", "3": "Ammonia is used in some refrigeration, not as dry ice."}'),
  ('GK-0011', 'Everyday science', 'Chemistry around us', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Chemistry 11 (PECTAA), acids and bases', 'The chemical name of baking soda is:', '["Calcium carbonate", "Sodium chloride", "Sodium hydroxide", "Sodium bicarbonate"]', 3, 'Baking soda is sodium hydrogen carbonate (NaHCO3); it releases carbon dioxide when heated or mixed with acid.', '{"0": "Calcium carbonate is chalk or limestone.", "1": "Sodium chloride is common salt.", "2": "Sodium hydroxide is caustic soda."}'),
  ('GK-0012', 'Everyday science', 'Chemistry around us', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Chemistry 11 (PECTAA), nitrogen compounds', 'Nitrous oxide (N2O) is commonly called:', '["Marsh gas", "Laughing gas", "Tear gas", "Noble gas"]', 1, 'Nitrous oxide causes mild euphoria and is used as an anaesthetic.', '{"0": "Marsh gas is methane.", "2": "Tear gas is a different irritant compound.", "3": "Noble gases are helium, neon, argon and others."}'),
  ('GK-0013', 'Everyday science', 'Physics around us', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Physics 11 (PECTAA), measurements', 'The SI unit of electric current is the:', '["Ampere", "Ohm", "Watt", "Volt"]', 0, 'Current is measured in amperes (A), named after André-Marie Ampère.', '{"1": "The ohm is the unit of resistance.", "2": "The watt is the unit of power.", "3": "The volt is the unit of potential difference."}'),
  ('GK-0014', 'Everyday science', 'Physics around us', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Physics 11 (PECTAA), waves', 'Sound cannot travel through:', '["Air", "A vacuum", "Water", "Steel"]', 1, 'Sound is a vibration of particles, so it needs a medium; there are no particles in a vacuum.', '{"0": "Sound normally reaches us through air.", "2": "Sound travels faster in water than in air.", "3": "Sound travels very fast through steel."}'),
  ('GK-0015', 'Everyday science', 'Physics around us', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Physics 11 (PECTAA), waves and light', 'The speed of light in a vacuum is about:', '["300 km per second", "340 metres per second", "3,000 km per second", "300,000 km per second"]', 3, 'Light travels at about 3 × 10^8 m/s, which is 300,000 km/s.', '{"0": "That is a thousand times too slow.", "1": "About 340 m/s is the speed of sound in air.", "2": "That is a hundred times too slow."}'),
  ('GK-0016', 'Everyday science', 'Space', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: NASA Solar System facts, Jupiter', 'The largest planet in the Solar System is:', '["Saturn", "Jupiter", "Neptune", "Earth"]', 1, 'Jupiter''s mass is more than twice that of all the other planets combined.', '{"0": "Saturn is the second largest.", "2": "Neptune is the fourth largest.", "3": "Earth is the largest of the rocky planets only."}'),
  ('GK-0017', 'Everyday science', 'Space', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: NASA Solar System facts, Mercury', 'The planet nearest to the Sun is:', '["Earth", "Mars", "Mercury", "Venus"]', 2, 'Mercury orbits closest to the Sun, once every 88 days.', '{"0": "Earth is third from the Sun.", "1": "Mars is fourth from the Sun.", "3": "Venus is second from the Sun."}'),
  ('GK-0018', 'Everyday science', 'Space', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: NASA Solar System facts, Mars', 'Which planet is known as the ''Red Planet''?', '["Venus", "Mercury", "Jupiter", "Mars"]', 3, 'Iron oxide (rust) in its soil gives Mars its red colour.', '{"0": "Venus is the brightest planet, sometimes called the morning star.", "1": "Mercury is grey.", "2": "Jupiter is known for its Great Red Spot, but it is not the Red Planet."}'),
  ('GK-0019', 'Everyday science', 'Discoveries', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Biology 12 (PECTAA), pharmacology', 'Penicillin, the first antibiotic, was discovered by:', '["Alexander Fleming", "Robert Koch", "Edward Jenner", "Louis Pasteur"]', 0, 'Fleming noticed in 1928 that a mould (Penicillium) killed bacteria around it.', '{"1": "Koch identified the bacteria that cause tuberculosis and cholera.", "2": "Jenner made the first vaccine, against smallpox.", "3": "Pasteur developed pasteurisation and vaccines for rabies and anthrax."}'),
  ('GK-0020', 'Everyday science', 'Discoveries', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Biology 12 (PECTAA), immunity', 'The first vaccine, against smallpox, was developed by:', '["Edward Jenner", "Jonas Salk", "Marie Curie", "Alexander Fleming"]', 0, 'In 1796 Jenner used cowpox to protect against smallpox; the word vaccine comes from ''vacca'', cow.', '{"1": "Salk developed a polio vaccine in the 1950s.", "2": "Marie Curie studied radioactivity.", "3": "Fleming discovered penicillin."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'General Knowledge', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('GK-0021', 'Everyday science', 'Inventions', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: General science, inventions', 'The telephone was invented by:', '["John Logie Baird", "Thomas Edison", "Guglielmo Marconi", "Alexander Graham Bell"]', 3, 'Bell received the patent for the telephone in 1876.', '{"0": "Baird demonstrated early television.", "1": "Edison is known for the light bulb and phonograph.", "2": "Marconi pioneered radio."}'),
  ('GK-0022', 'Everyday science', 'Inventions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: CERN, the birth of the Web', 'The World Wide Web was invented by:', '["Bill Gates", "Steve Jobs", "Charles Babbage", "Tim Berners-Lee"]', 3, 'Berners-Lee proposed the Web at CERN in 1989.', '{"0": "Bill Gates co-founded Microsoft.", "1": "Steve Jobs co-founded Apple.", "2": "Babbage designed early mechanical computers in the 1800s."}'),
  ('GK-0023', 'Everyday science', 'Inventions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Physics 11 (PECTAA), history of physics', 'Galileo Galilei is best known for using which instrument to study the sky?', '["Thermometer", "Telescope", "Microscope", "Barometer"]', 1, 'With his improved telescope (1609-10) Galileo saw Jupiter''s moons and the phases of Venus.', '{"0": "Galileo made an early thermoscope, but this is not what he is known for.", "2": "Galileo made a microscope too, but his fame rests on the telescope.", "3": "The barometer was invented by his pupil Torricelli."}'),
  ('GK-0024', 'World geography and countries', 'Oceans', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: National Geographic, oceans of the world', 'The largest ocean in the world is the:', '["Indian Ocean", "Arctic Ocean", "Pacific Ocean", "Atlantic Ocean"]', 2, 'The Pacific covers about a third of the Earth''s surface.', '{"0": "The Indian Ocean is the third largest.", "1": "The Arctic is the smallest.", "3": "The Atlantic is the second largest."}'),
  ('GK-0025', 'World geography and countries', 'Countries', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: CIA World Factbook, area ranking', 'The largest country in the world by area is:', '["China", "Canada", "United States", "Russia"]', 3, 'Russia covers about 17 million square kilometres, across Europe and Asia.', '{"0": "China is about the third or fourth largest.", "1": "Canada is the second largest.", "2": "The US is about the third or fourth largest."}'),
  ('GK-0026', 'World geography and countries', 'Countries', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: CIA World Factbook, Holy See (Vatican City)', 'The smallest country in the world is:', '["Maldives", "Monaco", "Vatican City", "San Marino"]', 2, 'Vatican City, inside Rome, covers about 0.44 square kilometres.', '{"0": "The Maldives is the smallest in Asia.", "1": "Monaco is the second smallest.", "3": "San Marino is the fifth smallest."}'),
  ('GK-0027', 'World geography and countries', 'Rivers', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica, Nile River', 'The longest river in the world is usually given as the:', '["Amazon", "Yangtze", "Indus", "Nile"]', 3, 'The Nile, about 6,650 km long, flows north to the Mediterranean through Egypt.', '{"0": "The Amazon carries the most water and is close in length, but the Nile is usually listed first.", "1": "The Yangtze is the longest in Asia.", "2": "The Indus is about 3,200 km long."}'),
  ('GK-0028', 'World geography and countries', 'Deserts', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica, Sahara', 'The largest hot desert in the world is the:', '["Gobi", "Thar", "Sahara", "Kalahari"]', 2, 'The Sahara covers most of North Africa, about 9 million square kilometres.', '{"0": "The Gobi is a cold desert in Mongolia and China.", "1": "The Thar lies in Pakistan and India and is much smaller.", "3": "The Kalahari is in southern Africa and is much smaller."}'),
  ('GK-0029', 'World geography and countries', 'Continents', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: National Geographic, continents', 'The largest continent is:', '["Europe", "Asia", "North America", "Africa"]', 1, 'Asia covers about 30 per cent of the world''s land.', '{"0": "Europe is one of the smallest.", "2": "North America is the third largest.", "3": "Africa is the second largest."}'),
  ('GK-0030', 'World geography and countries', 'Countries', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: CIA World Factbook, Turkey', 'Which country lies partly in Europe and partly in Asia?', '["Iran", "Greece", "Turkey", "Egypt"]', 2, 'Turkey''s Thrace region, west of the Bosphorus, is in Europe; Anatolia is in Asia.', '{"0": "Iran is wholly in Asia.", "1": "Greece is wholly in Europe.", "3": "Egypt is in Africa, with Sinai in Asia, but not in Europe."}'),
  ('GK-0031', 'World geography and countries', 'Capitals', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: CIA World Factbook, Australia', 'The capital of Australia is:', '["Sydney", "Melbourne", "Perth", "Canberra"]', 3, 'Canberra was built as a compromise between Sydney and Melbourne.', '{"0": "Sydney is the largest city but not the capital.", "1": "Melbourne was the temporary capital until 1927.", "2": "Perth is the capital of Western Australia."}'),
  ('GK-0032', 'World geography and countries', 'Capitals', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: CIA World Factbook, Turkey', 'The capital of Turkey is:', '["Izmir", "Konya", "Istanbul", "Ankara"]', 3, 'Ankara has been the capital since the Republic was founded in 1923.', '{"0": "Izmir is a port on the Aegean.", "1": "Konya is a city in central Anatolia.", "2": "Istanbul is the largest city and was the Ottoman capital."}'),
  ('GK-0033', 'World geography and countries', 'Capitals', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: CIA World Factbook, Malaysia', 'Kuala Lumpur is the capital of:', '["Indonesia", "Brunei", "Thailand", "Malaysia"]', 3, 'Kuala Lumpur is Malaysia''s capital, though many government offices moved to Putrajaya.', '{"0": "Indonesia''s capital is Jakarta.", "1": "Brunei''s capital is Bandar Seri Begawan.", "2": "Thailand''s capital is Bangkok."}'),
  ('GK-0034', 'World geography and countries', 'Capitals', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: CIA World Factbook, Canada', 'The capital of Canada is:', '["Toronto", "Ottawa", "Vancouver", "Montreal"]', 1, 'Ottawa, in Ontario, has been the capital since 1857.', '{"0": "Toronto is the largest city.", "2": "Vancouver is on the Pacific coast.", "3": "Montreal is the largest French-speaking city."}'),
  ('GK-0035', 'World geography and countries', 'Currencies', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Bangladesh Bank', 'The currency of Bangladesh is the:', '["Afghani", "Taka", "Ringgit", "Rupee"]', 1, 'Bangladesh''s currency is the taka.', '{"0": "The afghani is Afghanistan''s currency.", "2": "The ringgit is Malaysia''s currency.", "3": "The rupee is used in Pakistan, India, Sri Lanka and Nepal."}'),
  ('GK-0036', 'World geography and countries', 'Currencies', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Bank of Japan', 'The currency of Japan is the:', '["Won", "Yuan", "Yen", "Baht"]', 2, 'Japan''s currency is the yen.', '{"0": "The won is used in North and South Korea.", "1": "The yuan (renminbi) is China''s currency.", "3": "The baht is Thailand''s currency."}'),
  ('GK-0037', 'World geography and countries', 'Nicknames', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: General knowledge, country nicknames', 'Which country is called the ''Land of the Rising Sun''?', '["China", "Norway", "Japan", "Finland"]', 2, 'Japan''s own name, Nihon, means ''origin of the sun''.', '{"0": "China is sometimes called the Middle Kingdom.", "1": "Norway is called the Land of the Midnight Sun.", "3": "Finland is called the Land of a Thousand Lakes."}'),
  ('GK-0038', 'World geography and countries', 'Waterways', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Suez Canal Authority', 'The Suez Canal connects the Mediterranean Sea with the:', '["Black Sea", "Atlantic Ocean", "Arabian Sea", "Red Sea"]', 3, 'The Suez Canal in Egypt opened in 1869 and shortens the route from Europe to Asia.', '{"0": "The Black Sea is linked to the Mediterranean through the Bosphorus.", "1": "The Strait of Gibraltar links the Mediterranean with the Atlantic.", "2": "The Red Sea leads on to the Arabian Sea, but the canal ends at the Red Sea."}'),
  ('GK-0039', 'World geography and countries', 'Waterways', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica, Strait of Gibraltar', 'The Strait of Gibraltar connects the Mediterranean Sea with the:', '["Red Sea", "Black Sea", "Atlantic Ocean", "Indian Ocean"]', 2, 'The strait separates Spain from Morocco.', '{"0": "The Suez Canal links the Mediterranean with the Red Sea.", "1": "The Bosphorus and Dardanelles link to the Black Sea.", "3": "The Mediterranean reaches the Indian Ocean only via Suez and the Red Sea."}'),
  ('GK-0040', 'World geography and countries', 'Waterways', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: US Energy Information Administration, World Oil Transit Chokepoints', 'A large share of the world''s seaborne oil passes through which strait between Iran and Oman?', '["Strait of Hormuz", "Bosphorus", "Bab-el-Mandeb", "Strait of Malacca"]', 0, 'The Strait of Hormuz links the Persian Gulf with the Gulf of Oman.', '{"1": "The Bosphorus is in Turkey.", "2": "Bab-el-Mandeb lies between Yemen and Djibouti.", "3": "Malacca lies between Malaysia and Indonesia."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'General Knowledge', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('GK-0041', 'World geography and countries', 'Extremes', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica, Dead Sea', 'The lowest point on land on Earth is the shore of the:', '["Caspian Sea", "Death Valley", "Mariana Trench", "Dead Sea"]', 3, 'The Dead Sea shore, between Jordan and Israel, is over 400 metres below sea level.', '{"0": "The Caspian shore is below sea level, but much less so.", "1": "Death Valley is the lowest point in North America.", "2": "The Mariana Trench is the deepest point of the ocean, not land."}'),
  ('GK-0042', 'World geography and countries', 'Mountains', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica, Mount Everest', 'Mount Everest lies on the border of Nepal and:', '["Bhutan", "China", "Pakistan", "India"]', 1, 'Everest (8,849 m) is on the border between Nepal and the Tibet region of China.', '{"0": "Bhutan lies to the east of Everest.", "2": "Pakistan''s highest peak is K2.", "3": "India does not border Everest."}'),
  ('GK-0043', 'International organisations and treaties', 'United Nations', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: United Nations, history of the UN', 'The United Nations was founded in:', '["1948", "1945", "1919", "1939"]', 1, 'The UN Charter came into force on 24 October 1945, now marked as UN Day.', '{"0": "1948 is the year of the Universal Declaration of Human Rights.", "2": "The League of Nations was created after the 1919 peace conference.", "3": "1939 is when the Second World War began."}'),
  ('GK-0044', 'International organisations and treaties', 'United Nations', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: United Nations, headquarters', 'The headquarters of the United Nations is in:', '["New York", "The Hague", "Paris", "Geneva"]', 0, 'UN headquarters is in Manhattan, New York.', '{"1": "The Hague hosts the International Court of Justice.", "2": "Paris hosts UNESCO.", "3": "Geneva hosts the UN''s European office and many agencies."}'),
  ('GK-0045', 'International organisations and treaties', 'United Nations', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: UN Charter, Article 23', 'How many permanent members does the UN Security Council have?', '["Ten", "Five", "Fifteen", "Seven"]', 1, 'The permanent five are China, France, Russia, the United Kingdom and the United States; each has a veto.', '{"0": "Ten is the number of non-permanent members.", "2": "Fifteen is the total membership of the Council.", "3": "There are five permanent members."}'),
  ('GK-0046', 'International organisations and treaties', 'United Nations', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: UN Charter, Article 23', 'Which of these is NOT a permanent member of the UN Security Council?', '["France", "Germany", "China", "Russia"]', 1, 'Germany has served as a non-permanent member but has no permanent seat.', '{"0": "France is a permanent member.", "2": "China is a permanent member.", "3": "Russia holds the seat once held by the Soviet Union."}'),
  ('GK-0047', 'International organisations and treaties', 'United Nations', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: United Nations, official languages', 'How many official languages does the United Nations have?', '["Four", "Eight", "Five", "Six"]', 3, 'Arabic, Chinese, English, French, Russian and Spanish.', '{"0": "There are six official languages.", "1": "There are six official languages.", "2": "Arabic was added in 1973, making six."}'),
  ('GK-0048', 'International organisations and treaties', 'United Nations', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: United Nations, Charter of the United Nations', 'The UN Charter was signed in 1945 at:', '["New York", "San Francisco", "Yalta", "London"]', 1, 'The Charter was signed on 26 June 1945 at the San Francisco Conference.', '{"0": "New York became the UN''s home later.", "2": "Yalta hosted a wartime summit in February 1945.", "3": "London hosted the first General Assembly in 1946."}'),
  ('GK-0049', 'International organisations and treaties', 'United Nations', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: United Nations, former Secretaries-General', 'The first Secretary-General of the United Nations was:', '["Dag Hammarskjöld", "Trygve Lie", "Kofi Annan", "U Thant"]', 1, 'Trygve Lie of Norway served from 1946 to 1952.', '{"0": "Hammarskjöld was the second Secretary-General.", "2": "Kofi Annan was the seventh Secretary-General.", "3": "U Thant was the third Secretary-General."}'),
  ('GK-0050', 'International organisations and treaties', 'UN agencies', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Health Organization, about WHO', 'The headquarters of the World Health Organization is in:', '["New York", "Rome", "Vienna", "Geneva"]', 3, 'WHO was set up in 1948 with its headquarters in Geneva, Switzerland.', '{"0": "New York hosts UN headquarters and UNICEF.", "1": "Rome hosts the FAO.", "2": "Vienna hosts the IAEA."}'),
  ('GK-0051', 'International organisations and treaties', 'UN agencies', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: UNESCO, about us', 'UNESCO''s headquarters is in:', '["Rome", "Paris", "Geneva", "Nairobi"]', 1, 'UNESCO, the UN body for education, science and culture, is based in Paris.', '{"0": "Rome hosts the FAO.", "2": "Geneva hosts WHO and the ILO.", "3": "Nairobi hosts the UN Environment Programme."}'),
  ('GK-0052', 'International organisations and treaties', 'UN agencies', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: FAO, about FAO', 'The Food and Agriculture Organization (FAO) has its headquarters in:', '["Paris", "Rome", "Vienna", "Washington"]', 1, 'The FAO is headquartered in Rome, Italy.', '{"0": "Paris hosts UNESCO.", "2": "Vienna hosts the IAEA.", "3": "Washington hosts the IMF and World Bank."}'),
  ('GK-0053', 'International organisations and treaties', 'UN agencies', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: IAEA, about us', 'The International Atomic Energy Agency (IAEA) is based in:', '["Brussels", "New York", "Geneva", "Vienna"]', 3, 'The IAEA, founded in 1957, is headquartered in Vienna, Austria.', '{"0": "Brussels hosts NATO and the EU.", "1": "New York hosts UN headquarters.", "2": "Geneva hosts WHO."}'),
  ('GK-0054', 'International organisations and treaties', 'Financial institutions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: International Monetary Fund, history', 'The IMF and the World Bank were planned at a conference held in 1944 at:', '["Bretton Woods", "Yalta", "San Francisco", "Geneva"]', 0, 'The Bretton Woods Conference in New Hampshire, USA, created both institutions; both are based in Washington, DC.', '{"1": "Yalta hosted a wartime summit in 1945.", "2": "San Francisco hosted the 1945 UN conference.", "3": "Geneva was the home of the League of Nations."}'),
  ('GK-0055', 'International organisations and treaties', 'Trade', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Trade Organization, history', 'The World Trade Organization (WTO) was set up in:', '["2001", "1945", "1995", "1947"]', 2, 'The WTO replaced GATT on 1 January 1995; it is based in Geneva.', '{"0": "2001 is when the Doha round of talks began.", "1": "1945 is when the UN was founded.", "3": "1947 is when GATT, the WTO''s forerunner, was signed."}'),
  ('GK-0056', 'International organisations and treaties', 'Regional organisations', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: SAARC Secretariat, about SAARC', 'The secretariat of SAARC is in:', '["New Delhi", "Islamabad", "Kathmandu", "Dhaka"]', 2, 'SAARC was founded in Dhaka in 1985; its permanent secretariat opened in Kathmandu, Nepal, in 1987.', '{"0": "New Delhi hosts no SAARC secretariat.", "1": "Islamabad hosted SAARC summits but not the secretariat.", "3": "Dhaka hosted the first SAARC summit in 1985."}'),
  ('GK-0057', 'International organisations and treaties', 'Regional organisations', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: SAARC Secretariat, member states', 'How many member states does SAARC have?', '["Eight", "Seven", "Six", "Ten"]', 0, 'Afghanistan, Bangladesh, Bhutan, India, Maldives, Nepal, Pakistan and Sri Lanka.', '{"1": "It had seven until Afghanistan joined in 2007.", "2": "SAARC began with seven members.", "3": "ASEAN has ten members; SAARC has eight."}'),
  ('GK-0058', 'International organisations and treaties', 'Regional organisations', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: NATO, history', 'The headquarters of NATO is in:', '["Paris", "Washington", "London", "Brussels"]', 3, 'NATO, founded in 1949, has been based in Brussels, Belgium, since 1967.', '{"0": "NATO was based in Paris until 1967.", "1": "The North Atlantic Treaty was signed in Washington, but NATO is based in Brussels.", "2": "London was NATO''s first home in 1949-52."}'),
  ('GK-0059', 'International organisations and treaties', 'Regional organisations', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Charter of the Organisation of Islamic Cooperation (2008)', 'The General Secretariat of the Organisation of Islamic Cooperation (OIC) is in:', '["Cairo", "Jeddah", "Rabat", "Riyadh"]', 1, 'The OIC''s secretariat is in Jeddah, Saudi Arabia, pending a planned move to Jerusalem.', '{"0": "Cairo hosts the Arab League.", "2": "Rabat hosted the first OIC summit in 1969.", "3": "Riyadh is the Saudi capital but not the OIC''s seat."}'),
  ('GK-0060', 'International organisations and treaties', 'Regional organisations', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: League of Arab States, about', 'The headquarters of the Arab League is in:', '["Jeddah", "Riyadh", "Cairo", "Baghdad"]', 2, 'The Arab League was founded in Cairo in 1945 and is based there.', '{"0": "Jeddah hosts the OIC.", "1": "Riyadh is the capital of Saudi Arabia.", "3": "Baghdad is not the League''s seat."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'General Knowledge', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('GK-0061', 'International organisations and treaties', 'Treaties', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: United Nations, Universal Declaration of Human Rights', 'The Universal Declaration of Human Rights was adopted by the UN General Assembly on:', '["26 June 1945", "4 July 1776", "10 December 1948", "24 October 1945"]', 2, 'The UDHR was adopted in Paris on 10 December 1948, now Human Rights Day.', '{"0": "26 June 1945 is when the UN Charter was signed.", "1": "4 July 1776 is the US Declaration of Independence.", "3": "24 October 1945 is when the UN came into being."}'),
  ('GK-0062', 'International organisations and treaties', 'Treaties', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: UN Convention on the Law of the Sea 1982, Articles 3, 33 and 57', 'Under the UN Convention on the Law of the Sea, a country''s territorial sea extends up to:', '["200 nautical miles", "24 nautical miles", "12 nautical miles", "3 nautical miles"]', 2, 'UNCLOS Article 3: a state may set its territorial sea up to 12 nautical miles from its baselines.', '{"0": "200 nautical miles is the exclusive economic zone.", "1": "24 nautical miles is the outer limit of the contiguous zone.", "3": "3 nautical miles was an older custom, not the UNCLOS rule."}'),
  ('GK-0063', 'Law, courts and the Constitution', 'Courts', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: UN Charter, Article 92; Statute of the ICJ, Article 22', 'The principal judicial organ of the United Nations, the International Court of Justice, sits at:', '["Geneva", "New York", "Strasbourg", "The Hague"]', 3, 'The ICJ sits in the Peace Palace, The Hague, Netherlands (UN Charter, Article 92).', '{"0": "Geneva hosts the Human Rights Council and many agencies.", "1": "New York hosts UN headquarters.", "2": "Strasbourg hosts the European Court of Human Rights."}'),
  ('GK-0064', 'Law, courts and the Constitution', 'Courts', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of Pakistan 1973, Article 183', 'The Supreme Court of Pakistan sits permanently at:', '["Islamabad", "Lahore", "Rawalpindi", "Karachi"]', 0, 'Article 183: the permanent seat of the Supreme Court is Islamabad.', '{"1": "Lahore has a branch registry and the Lahore High Court.", "2": "The Supreme Court sat in Rawalpindi before its Islamabad building opened.", "3": "Karachi has a branch registry and the Sindh High Court."}'),
  ('GK-0065', 'Law, courts and the Constitution', 'Courts', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of Pakistan 1973, Article 203C', 'The Federal Shariat Court, which can strike down laws against the injunctions of Islam, was set up in:', '["1980", "2010", "1956", "1973"]', 0, 'Chapter 3A (Articles 203A-203J), added in 1980, created the Federal Shariat Court.', '{"1": "2010 is the Eighteenth Amendment.", "2": "1956 is the year of the first Constitution.", "3": "The 1973 Constitution did not at first have this court."}'),
  ('GK-0066', 'Law, courts and the Constitution', 'Legal terms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of Pakistan 1973, Article 199(1)(b)(i)', 'The writ of habeas corpus is used to:', '["have a detained person brought before a court", "ask by what authority someone holds an office", "order an official to do a public duty", "stop a lower court from hearing a case"]', 0, 'Habeas corpus means ''you may have the body''; the court checks whether the detention is lawful. In Pakistan, High Courts issue it under Article 199.', '{"1": "That is a writ of quo warranto.", "2": "That is a writ of mandamus.", "3": "That is a writ of prohibition."}'),
  ('GK-0067', 'Law, courts and the Constitution', 'Legal terms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Black''s Law Dictionary, audi alteram partem', 'The legal maxim ''audi alteram partem'' means:', '["hear the other side", "let the buyer beware", "no one should be a judge in his own cause", "the thing speaks for itself"]', 0, 'It is a rule of natural justice: no one should be condemned unheard.', '{"1": "That is caveat emptor.", "2": "That is nemo judex in causa sua.", "3": "That is res ipsa loquitur."}'),
  ('GK-0068', 'Law, courts and the Constitution', 'Legal terms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of Pakistan 1973, Article 184(3)', 'When a court acts ''suo motu'', it acts:', '["on its own motion, without a petition", "after both parties agree", "in the absence of the accused", "only on appeal"]', 0, 'The Supreme Court of Pakistan takes suo motu notice under Article 184(3) in matters of public importance.', '{"1": "That would be by consent.", "2": "That is ''in absentia''.", "3": "Suo motu action starts a case without any party bringing it."}'),
  ('GK-0069', 'Law, courts and the Constitution', 'Legal terms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Black''s Law Dictionary, sub judice', 'A matter that is ''sub judice'' is:', '["already decided and final", "decided in someone''s absence", "under consideration by a court", "outside the court''s power"]', 2, 'Comment that could prejudice a sub judice case may be contempt of court.', '{"0": "A finally decided matter is ''res judicata''.", "1": "That is ''in absentia''.", "3": "An act beyond legal power is ''ultra vires''."}'),
  ('GK-0070', 'Law, courts and the Constitution', 'Legal terms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Black''s Law Dictionary, ultra vires', 'An act done beyond the legal powers of the person or body doing it is said to be:', '["de facto", "intra vires", "bona fide", "ultra vires"]', 3, 'Courts can declare ultra vires rules and orders void.', '{"0": "De facto means in fact, as opposed to in law.", "1": "Intra vires means within one''s powers.", "2": "Bona fide means in good faith."}'),
  ('GK-0071', 'Law, courts and the Constitution', 'Legal terms', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Black''s Law Dictionary, amicus curiae', 'A person who is not a party but assists the court on a point of law is called:', '["guarantor", "respondent", "plaintiff", "amicus curiae"]', 3, 'Amicus curiae means ''friend of the court''; Pakistani courts often appoint senior lawyers in this role.', '{"0": "A guarantor promises to pay another''s debt.", "1": "The respondent answers a petition or appeal.", "2": "The plaintiff brings a civil suit."}'),
  ('GK-0072', 'Law, courts and the Constitution', 'Legal terms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Black''s Law Dictionary, affidavit', 'A written statement of facts made on oath is called an:', '["Injunction", "Indictment", "Affidavit", "Appeal"]', 2, 'An affidavit is sworn before an oath commissioner or magistrate.', '{"0": "An injunction is a court order to do or not do something.", "1": "An indictment is a formal charge of a crime.", "3": "An appeal asks a higher court to review a decision."}'),
  ('GK-0073', 'Law, courts and the Constitution', 'Laws of Pakistan', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Pakistan Penal Code (Act XLV of 1860)', 'The Pakistan Penal Code dates from:', '["1984", "1860", "1908", "1898"]', 1, 'The Penal Code, drafted under Lord Macaulay, was enacted in 1860 and still forms the base of Pakistan''s criminal law.', '{"0": "1984 is the Qanun-e-Shahadat Order.", "2": "1908 is the Code of Civil Procedure.", "3": "1898 is the Code of Criminal Procedure."}'),
  ('GK-0074', 'Law, courts and the Constitution', 'Laws of Pakistan', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Qanun-e-Shahadat Order 1984 (President''s Order 10 of 1984)', 'The law of evidence in Pakistan is the:', '["Contract Act 1872", "Qanun-e-Shahadat Order 1984", "Pakistan Penal Code 1860", "Code of Civil Procedure 1908"]', 1, 'The Qanun-e-Shahadat Order 1984 replaced the Evidence Act 1872.', '{"0": "The Contract Act governs agreements.", "2": "The PPC defines crimes and punishments.", "3": "The CPC governs civil court procedure."}'),
  ('GK-0075', 'Law, courts and the Constitution', 'Constitution', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of Pakistan 1973, Article 25A', 'Free and compulsory education for children aged 5 to 16 is a fundamental right under Article:', '["25A", "9", "10A", "19A"]', 0, 'Article 25A was added by the Eighteenth Amendment in 2010.', '{"1": "Article 9 is the right to life and liberty.", "2": "Article 10A is the right to a fair trial.", "3": "Article 19A is the right to information."}'),
  ('GK-0076', 'Law, courts and the Constitution', 'Constitution', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of Pakistan 1973, Article 6', 'Which Article of the Constitution makes abrogating or subverting the Constitution ''high treason''?', '["Article 6", "Article 25", "Article 62", "Article 9"]', 0, 'Article 6(1): anyone who abrogates or subverts the Constitution by force or other unconstitutional means is guilty of high treason.', '{"1": "Article 25 guarantees equality of citizens.", "2": "Article 62 sets the qualifications for members of Parliament.", "3": "Article 9 protects life and liberty."}'),
  ('GK-0077', 'Law, courts and the Constitution', 'History of law', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: The British Library, Magna Carta', 'The Magna Carta, a landmark charter limiting the king''s power, was sealed in England in:', '["1689", "1776", "1066", "1215"]', 3, 'King John sealed the Magna Carta at Runnymede in 1215.', '{"0": "1689 is the English Bill of Rights.", "1": "1776 is the US Declaration of Independence.", "2": "1066 is the Norman Conquest of England."}'),
  ('GK-0078', 'Famous people, books and firsts', 'Books', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica, Das Kapital', '''Das Kapital'' was written by:', '["Karl Marx", "Adam Smith", "Lenin", "Thomas Hobbes"]', 0, 'Marx published the first volume of Das Kapital in 1867.', '{"1": "Adam Smith wrote ''The Wealth of Nations''.", "2": "Lenin led the Russian Revolution and wrote ''What Is to Be Done?''.", "3": "Hobbes wrote ''Leviathan''."}'),
  ('GK-0079', 'Famous people, books and firsts', 'Books', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica, Republic (Plato)', '''The Republic'' was written by:', '["Aristotle", "Plato", "Machiavelli", "Socrates"]', 1, 'Plato''s Republic describes an ideal state ruled by philosopher-kings.', '{"0": "Aristotle wrote ''Politics''.", "2": "Machiavelli wrote ''The Prince''.", "3": "Socrates wrote nothing himself; he speaks in Plato''s dialogues."}'),
  ('GK-0080', 'Famous people, books and firsts', 'Books', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica, The Prince', '''The Prince'' was written by:', '["Niccolò Machiavelli", "Jean-Jacques Rousseau", "John Locke", "Thomas Hobbes"]', 0, 'Machiavelli wrote The Prince in about 1513, advice to rulers on keeping power.', '{"1": "Rousseau wrote ''The Social Contract''.", "2": "Locke wrote ''Two Treatises of Government''.", "3": "Hobbes wrote ''Leviathan''."}')
