INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'General Knowledge', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('GK-0081', 'Famous people, books and firsts', 'Books', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica, The Social Contract', '''The Social Contract'' (1762) was written by:', '["Jean-Jacques Rousseau", "John Locke", "Montesquieu", "Voltaire"]', 0, 'Rousseau''s work opens: ''Man is born free, and everywhere he is in chains.''', '{"1": "Locke wrote ''Two Treatises of Government'' (1689).", "2": "Montesquieu wrote ''The Spirit of the Laws''.", "3": "Voltaire wrote ''Candide''."}'),
  ('GK-0082', 'Famous people, books and firsts', 'Books', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica, Montesquieu', 'The idea of separation of powers among the legislature, executive and judiciary is most linked to:', '["Thomas Hobbes", "Karl Marx", "Montesquieu", "Plato"]', 2, 'Montesquieu set out the idea in ''The Spirit of the Laws'' (1748).', '{"0": "Hobbes argued for a strong single sovereign.", "1": "Marx wrote about class struggle.", "3": "Plato argued for rule by philosopher-kings."}'),
  ('GK-0083', 'Famous people, books and firsts', 'Books', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Iqbal Academy Pakistan, works of Iqbal', '''Bang-e-Dra'', a collection of Urdu poems, is by:', '["Allama Muhammad Iqbal", "Faiz Ahmad Faiz", "Mirza Ghalib", "Altaf Hussain Hali"]', 0, 'Bang-e-Dra (1924) was Iqbal''s first Urdu collection; it includes ''Shikwa'' and ''Jawab-e-Shikwa''.', '{"1": "Faiz''s books include ''Naqsh-e-Faryadi''.", "2": "Ghalib''s Urdu poems are in his Diwan.", "3": "Hali wrote the Musaddas."}'),
  ('GK-0084', 'Famous people, books and firsts', 'Books', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica, The Wealth of Nations', '''The Wealth of Nations'' (1776), the founding book of modern economics, was written by:', '["Adam Smith", "Karl Marx", "John Maynard Keynes", "David Ricardo"]', 0, 'Adam Smith argued that free markets, guided by self-interest, raise national wealth.', '{"1": "Marx wrote ''Das Kapital''.", "2": "Keynes wrote ''The General Theory'' in 1936.", "3": "Ricardo wrote on comparative advantage in 1817."}'),
  ('GK-0085', 'Famous people, books and firsts', 'Firsts', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Pakistan Studies (compulsory), Political history', 'Who was the first woman Prime Minister of Pakistan?', '["Fatima Jinnah", "Benazir Bhutto", "Fehmida Mirza", "Begum Ra''ana Liaquat Ali Khan"]', 1, 'Benazir Bhutto became Prime Minister in December 1988, the first woman to lead a Muslim-majority country.', '{"0": "Fatima Jinnah contested the 1965 presidential election but was never Prime Minister.", "2": "Fehmida Mirza was the first woman Speaker of the National Assembly.", "3": "She was Governor of Sindh, not Prime Minister."}'),
  ('GK-0086', 'Famous people, books and firsts', 'Firsts', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: NASA, Apollo 11 mission', 'The first person to walk on the Moon was:', '["Neil Armstrong", "Buzz Aldrin", "Michael Collins", "Yuri Gagarin"]', 0, 'Armstrong stepped onto the Moon on 20 July 1969 (Apollo 11).', '{"1": "Aldrin stepped onto the Moon after Armstrong.", "2": "Collins stayed in orbit in the command module.", "3": "Gagarin was the first person in space, in 1961."}'),
  ('GK-0087', 'Famous people, books and firsts', 'Firsts', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica, Yuri Gagarin', 'The first human to travel into space was:', '["Valentina Tereshkova", "Alan Shepard", "Yuri Gagarin", "Neil Armstrong"]', 2, 'Gagarin orbited the Earth in Vostok 1 on 12 April 1961.', '{"0": "Tereshkova was the first woman in space, in 1963.", "1": "Shepard was the first American in space, weeks after Gagarin.", "3": "Armstrong was the first to walk on the Moon, in 1969."}'),
  ('GK-0088', 'Famous people, books and firsts', 'Nobel Prize', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Nobel Prize, Physics 1979', 'The first Pakistani to win a Nobel Prize was:', '["Dr Abdus Salam", "Dr Abdul Qadeer Khan", "Malala Yousafzai", "Dr Atta-ur-Rahman"]', 0, 'Abdus Salam shared the 1979 Nobel Prize in Physics for work on the electroweak theory.', '{"1": "Dr A. Q. Khan did not win a Nobel Prize.", "2": "Malala won the Peace Prize in 2014, after Abdus Salam.", "3": "Dr Atta-ur-Rahman is a chemist who has not won a Nobel Prize."}'),
  ('GK-0089', 'Famous people, books and firsts', 'Nobel Prize', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Nobel Prize, Peace 2014', 'Malala Yousafzai won the Nobel Peace Prize in:', '["2013", "2014", "2016", "2012"]', 1, 'She shared the 2014 Peace Prize with Kailash Satyarthi and is the youngest Nobel laureate.', '{"0": "In 2013 she addressed the UN, but the prize came a year later.", "2": "The prize came in 2014.", "3": "2012 is the year she was attacked in Swat."}'),
  ('GK-0090', 'Famous people, books and firsts', 'Muslim scholars', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica, al-Biruni', 'Kitab al-Hind, a study of Indian society and science, was written by:', '["Al-Biruni", "Ibn Khaldun", "Ibn Battuta", "Al-Masudi"]', 0, 'Al-Biruni came to India with Mahmud of Ghazni and wrote Kitab al-Hind in about 1030.', '{"1": "Ibn Khaldun wrote the Muqaddimah.", "2": "Ibn Battuta wrote a travel book, the Rihla.", "3": "Al-Masudi wrote ''The Meadows of Gold''."}'),
  ('GK-0091', 'Sports, awards and days', 'Cricket', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: ICC, Cricket World Cup 1992', 'Pakistan won the Cricket World Cup in 1992 under the captaincy of:', '["Javed Miandad", "Imran Khan", "Wasim Akram", "Inzamam-ul-Haq"]', 1, 'Pakistan beat England in the final at Melbourne on 25 March 1992.', '{"0": "Miandad was a key batter in that team but not the captain.", "2": "Wasim Akram was man of the match in the final.", "3": "Inzamam was a young batter in the team."}'),
  ('GK-0092', 'Sports, awards and days', 'Cricket', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: ICC, World Twenty20 2009', 'Pakistan won the ICC World Twenty20 in 2009, beating Sri Lanka in the final at:', '["Eden Gardens, Kolkata", "Melbourne Cricket Ground", "Lord''s, London", "The Oval, London"]', 2, 'Captained by Younis Khan, Pakistan won the final at Lord''s on 21 June 2009.', '{"0": "Kolkata hosted the 1987 World Cup final.", "1": "Melbourne hosted the 1992 World Cup final.", "3": "The Oval hosted the 2017 Champions Trophy final."}'),
  ('GK-0093', 'Sports, awards and days', 'Cricket', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: ICC, Champions Trophy 2017', 'Pakistan won the ICC Champions Trophy in 2017 by beating which team in the final?', '["India", "Australia", "England", "Sri Lanka"]', 0, 'Under Sarfaraz Ahmed, Pakistan beat India by 180 runs at The Oval on 18 June 2017.', '{"1": "Australia did not reach the final.", "2": "Pakistan beat England in the semi-final.", "3": "Pakistan beat Sri Lanka in a group match."}'),
  ('GK-0094', 'Sports, awards and days', 'Hockey', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: International Hockey Federation (FIH), World Cup history', 'How many times has Pakistan won the men''s Hockey World Cup?', '["Two", "Five", "Three", "Four"]', 3, 'Pakistan won in 1971, 1978, 1982 and 1994, more than any other country.', '{"0": "Pakistan has won it four times.", "1": "Pakistan has won it four times.", "2": "Pakistan has won it four times."}'),
  ('GK-0095', 'Sports, awards and days', 'Olympics', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Olympics.com, Paris 2024 men''s javelin', 'Arshad Nadeem won Olympic gold for Pakistan at Paris 2024 in:', '["Discus throw", "Hammer throw", "Shot put", "Javelin throw"]', 3, 'His throw of 92.97 m set an Olympic record and was Pakistan''s first individual Olympic gold.', '{"0": "His event is the javelin.", "1": "His event is the javelin.", "2": "His event is the javelin."}'),
  ('GK-0096', 'Sports, awards and days', 'Olympics', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: International Olympic Committee, Olympic rings', 'How many rings are there in the Olympic symbol?', '["Four", "Six", "Five", "Seven"]', 2, 'The five interlocking rings stand for the union of the five inhabited continents.', '{"0": "There are five rings.", "1": "There are five rings.", "3": "There are five rings."}'),
  ('GK-0097', 'Sports, awards and days', 'Squash', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Professional Squash Association, records', 'Jahangir Khan and Jansher Khan are world champions in:', '["Hockey", "Squash", "Snooker", "Tennis"]', 1, 'Jahangir Khan was unbeaten for over five years in the 1980s; Jansher Khan won eight World Open titles.', '{"0": "Pakistan''s hockey heroes include Islahuddin and Hassan Sardar.", "2": "Pakistan''s snooker champion is Muhammad Yousuf.", "3": "Pakistan''s best-known tennis player is Aisam-ul-Haq."}'),
  ('GK-0098', 'Sports, awards and days', 'Awards', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Inter Services Public Relations, Nishan-e-Haider', 'The highest military gallantry award of Pakistan is the:', '["Sitara-e-Imtiaz", "Nishan-e-Haider", "Hilal-e-Jurat", "Tamgha-e-Basalat"]', 1, 'The Nishan-e-Haider, named after Hazrat Ali (RA), is given for the highest bravery; most recipients received it after death.', '{"0": "Sitara-e-Imtiaz is a civil and military honour for distinguished service.", "2": "Hilal-e-Jurat is the second highest gallantry award.", "3": "Tamgha-e-Basalat is a lower gallantry award."}'),
  ('GK-0099', 'Sports, awards and days', 'Awards', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Inter Services Public Relations, Nishan-e-Haider recipients', 'The first Nishan-e-Haider was awarded to:', '["Captain Raja Muhammad Sarwar Shaheed", "Rashid Minhas Shaheed", "Major Shabbir Sharif Shaheed", "Major Aziz Bhatti Shaheed"]', 0, 'Captain Sarwar was martyred in Kashmir in July 1948, in the first war with India.', '{"1": "Rashid Minhas was awarded for 1971.", "2": "Major Shabbir Sharif was awarded for 1971.", "3": "Major Aziz Bhatti was awarded for the 1965 war."}'),
  ('GK-0100', 'Sports, awards and days', 'Days', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Government of Pakistan, national days', 'Pakistan Day, marking the Lahore Resolution, is observed on:', '["14 August", "23 March", "25 December", "6 September"]', 1, '23 March marks the Lahore Resolution of 1940 and the 1956 Constitution.', '{"0": "14 August is Independence Day.", "2": "25 December is Quaid-e-Azam Day.", "3": "6 September is Defence Day."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

